(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,55369,t=>{"use strict";let e={src:t.i(87569).default,width:800,height:1200,blurWidth:5,blurHeight:8,blurDataURL:"data:image/jpeg;base64,"};t.s(["default",0,e])},88834,t=>{"use strict";let e="skolko-tratit-na-marketing-proizvodstvu",i=t=>`/blog/${e}/${t}.webp`,s={slug:e,href:`/blog/${e}/`,hub:"ekonomika-klienta",kind:"article",label:"Гайд",published:"2026-10-16",tags:["бюджет","стоимость клиента","экономика","производство"],title:"Сколько производству тратить на маркетинг: считаем от маржи, а не от «5% выручки»",seoTitle:"Бюджет на маркетинг для производства: как рассчитать от маржи",description:"Как собственнику производства рассчитать бюджет на маркетинг: формула допустимой цены клиента, расчёт на трёх производствах, мощность цеха и длинный цикл сделки.",sub:"Формула, по которой бюджет считается за 15 минут: от маржи сделки, свободной мощности цеха и цикла продажи. С расчётами на кухнях, металлоизделиях и промышленном оборудовании.",meta:"12 минут чтения · экономика",cover:i("hero"),hero:{src:i("hero"),w:1600,h:900,alt:"Собственник производства изучает отчёт о продажах в кабинете с видом на цех",caption:"Бюджет на маркетинг — решение собственника, а не маркетолога: он упирается в маржу и мощность цеха"},shortAnswer:"Бюджет на маркетинг для производства считают не процентом от выручки, а от экономики сделки. Допустимая цена клиента = средний чек × маржинальность × доля маржи, которую вы готовы отдать на привлечение (мы ориентируемся на 15–30%). Умножьте её на число новых заказов, которые цех реально может взять, — это потолок бюджета вместе с оплатой подрядчиков. Пример: кухня за 300 000 ₽ при марже 30% и доле 25% — до 22 500 ₽ на клиента; при 8 свободных заказах в месяц — до 180 000 ₽ в месяц.",cases:["kitchens-rostov","industrial-robots","metal-factory-two-landings"],body:[{type:"p",text:"Вопрос «сколько тратить на маркетинг» собственник обычно задаёт в двух ситуациях: продажи встали и нужно больше заказов — или маркетолог просит увеличить бюджет, а проверить, оправдано ли это, нечем. В обоих случаях ответ «5–10% от выручки» не помогает. Он ничего не говорит о том, сколько стоит **ваш** клиент и сколько вы на нём зарабатываете."},{type:"p",text:"Ниже — расчёт, которым мы пользуемся перед каждым запуском. Он занимает 15 минут, и для него нужны четыре цифры, которые собственник производства знает и так: средний чек, маржа, конверсия заявки в договор и свободная мощность цеха."},{type:"h2",id:"procent-ot-vyruchki",text:"Почему «5–10% от выручки» не работает для производства"},{type:"p",text:"Процент от выручки — удобный ориентир для крупных компаний, где маркетинг — постоянная статья расходов на бренд. По данным Gartner, в 2025 году маркетинговые бюджеты компаний составили **7,7% выручки** — но в опросе участвовали в основном корпорации с выручкой больше 1 млрд долларов из США и Европы. Для производства с выручкой 10–50 млн ₽ в месяц эта цифра почти ничего не значит."},{type:"quote",text:"Маркетинговые бюджеты стабилизировались, но расходы застыли на уровне, которого многим директорам по маркетингу не хватает.",author:"Юэн Макинтайр",role:"вице-президент по аналитике, руководитель исследований практики маркетинга Gartner",source:"Gartner, 2025 CMO Spend Survey",sourceUrl:"https://www.gartner.com/en/newsroom/press-releases/2025-05-12-gartner-2025-cmo-spend-survey-reveals-marketing-budgets-have-flatlined-at-seven-percent-of-overall-company-revenue"},{type:"p",text:"У производства три особенности, из-за которых процент от выручки вводит в заблуждение:"},{type:"list",items:["**Маржа сильно отличается по продуктам.** Серийная металлоконструкция и проектная кухня с одинаковой выручкой приносят разную прибыль — значит, и платить за клиента вы можете по-разному.","**Мощность ограничена.** Цех не возьмёт больше заказов, чем позволяют станки и люди. Бюджет, который приводит клиентов сверх мощности, сжигает деньги и портит сроки.","**Сделка длинная.** Между расходом на рекламу и оплатой договора проходит от недели до полугода. Процент от выручки этого месяца не учитывает, что вы платите сегодня за деньги, которые придут через квартал."]},{type:"table",caption:"Четыре способа определить бюджет на маркетинг и чем они опасны для производства",head:["Способ","Как считают","Чем опасен для производства"],rows:[["Процент от выручки","5–10% прошлогодней выручки","Не учитывает маржу и мощность: в хороший год бюджет раздувается, в плохой — урезается, когда заказы нужнее всего"],["Как у конкурентов","Повторяем активность рынка","У конкурента другая маржа, другой цех и другой отдел продаж. Копируете расходы, но не результат"],["Сколько останется","Тратим, что свободно после всех платежей","Маркетинг включается и выключается рывками — каждый раз заново проходит период настройки"],["**От экономики клиента**","**Цена клиента × план новых заказов**","**Требует знать маржу и конверсию заявки в договор — зато бюджет привязан к прибыли**"]],highlight:2,note:"Последний способ — тот, которым пользуемся мы. Дальше — как его посчитать."},{type:"image",image:{src:i("meeting"),w:1600,h:900,alt:"Собственник производства и коммерческий директор считают бюджет на маркетинг за рабочим столом",caption:"Бюджет удобно считать вдвоём: собственник знает маржу, коммерческий директор — конверсию заявки в договор"}},{type:"h2",id:"formula",text:"Формула: сколько можно платить за одного клиента"},{type:"p",text:"Начинать нужно не с бюджета, а с **допустимой стоимости привлечения клиента** — максимума, который вы готовы потратить на маркетинг ради одного договора и всё ещё заработать."},{type:"key",title:"Формула",text:"Допустимая цена клиента = средний чек × маржинальность × доля маржи, которую вы готовы отдать на привлечение."},{type:"steps",items:["**Средний чек** — по договорам за последние 6–12 месяцев. Если продукт разный (опт и розница, серия и проект), считайте отдельно для каждого направления.","**Маржинальность** — сколько остаётся после материалов, работы цеха, доставки и монтажа. Не после всех расходов компании, а именно с одной сделки.","**Доля маржи на привлечение** — сколько из этой маржи вы готовы отдать, чтобы получить нового клиента. Мы ориентируемся на 15–30%: меньше — для крупных сделок с длинным циклом, больше — когда клиент возвращается с повторными заказами."]},{type:"image",image:{src:i("margin-layers"),w:1600,h:900,alt:"Объёмная схема: из цены заказа вычитаются материалы и работа цеха, остаётся маржа, часть которой идёт на привлечение клиента",caption:"Из чека вычитаем себестоимость — остаётся маржа. Только её часть можно отдать на привлечение клиента"}},{type:"p",text:"Важная деталь: в допустимую цену клиента должны поместиться **все** расходы на привлечение — рекламный бюджет, оплата подрядчика или штатного маркетолога, сервисы, иногда — бонус менеджеру за сделку. Яндекс в своём материале о стоимости привлечения клиента тоже советует считать её «расширенно»: реклама плюс зарплаты, программы и накладные расходы, делённые на число новых клиентов."},{type:"p",text:"Если клиент возвращается — например, завод металлоизделий получает от дилера 4–6 заказов в год, — считайте не маржу одной сделки, а маржу за всё время работы с клиентом. Иначе небольшой чек «запретит» любую рекламу, хотя на повторных заказах она окупается с запасом."},{type:"form",position:1},{type:"h2",id:"primery",text:"Считаем на трёх производствах"},{type:"p",text:"Чтобы перейти от цены клиента к цене заявки, нужна ещё одна цифра — **конверсия заявки в договор**. Её знает отдел продаж: сколько из 100 обращений заканчиваются оплатой. Делим допустимую цену клиента на неё — получаем, сколько можно платить за одну заявку."},{type:"table",caption:"Допустимая цена клиента и заявки на трёх производствах",head:["Показатель","Кухни на заказ","Металлоизделия","Промышленное оборудование"],rows:[["Средний чек","300 000 ₽","45 000 ₽ × 4 заказа в год","2 500 000 ₽"],["Маржинальность","30%","30%","25%"],["Маржа с клиента","90 000 ₽","54 000 ₽ за год","625 000 ₽"],["Доля маржи на привлечение","25%","25%","15%"],["**Допустимая цена клиента**","**22 500 ₽**","**13 500 ₽**","**93 750 ₽**"],["Конверсия заявки в договор","11%","20%","5% (квалифицированные заявки)"],["**Допустимая цена заявки**","**≈ 2 500 ₽**","**≈ 2 700 ₽**","**≈ 4 700 ₽**"],["Что получили в наших проектах","1 220 ₽ за заявку, 99 клиентов","3 216 ₽ за заявку","3 113 ₽ за квалифицированную заявку"]],highlight:1,note:"Чек, маржа и доля — условные, для примера. Конверсия 11% по кухням и цены заявок в последней строке — реальные цифры из наших кейсов."},{type:"p",text:"**Кухни.** В [проекте с производством кухонь в Ростове](/cases/kitchens-rostov/) из 890 заявок получилось 99 договоров — конверсия около 11%. При допустимых 2 500 ₽ за заявку фактические 1 220 ₽ означали, что реклама окупалась с двукратным запасом. Поэтому бюджет можно было спокойно наращивать, пока хватало мощности цеха."},{type:"p",text:"**Металлоизделия.** На одном заказе за 45 000 ₽ реклама почти не окупается: заявка в 3 216 ₽ при допустимых 2 700 ₽ — уже минус. Но если клиент заказывает 4 раза в год, картина другая. Поэтому для таких производств важно считать повторные заказы и работать с [дилерами и постоянными покупателями](/blog/rynki-sbyta/), а не только с разовыми."},{type:"p",text:"**Оборудование.** Здесь цикл сделки долгий, но и маржа с одного договора исчисляется сотнями тысяч. В [проекте с роботами-манипуляторами](/cases/industrial-robots/) квалифицированная заявка стоила 3 113 ₽ — даже при конверсии в сделку 5% это около 62 000 ₽ за договор при допустимых 93 750 ₽."},{type:"key",title:"Главное",text:"Сравнивайте цену заявки не с «рынком», а со своей допустимой ценой. Заявка за 4 000 ₽ может быть выгодной, а за 800 ₽ — убыточной: всё решают маржа и конверсия в договор."},{type:"h2",id:"byudzhet",text:"От цены клиента к бюджету: план и мощность цеха"},{type:"p",text:"Когда допустимая цена клиента известна, бюджет считается одной строкой:"},{type:"key",title:"Потолок бюджета в месяц",text:"Бюджет = допустимая цена клиента × число новых клиентов, которых вы можете обслужить."},{type:"p",text:"Число клиентов здесь — не «сколько хочется», а сколько заказов цех может взять сверх текущей загрузки. Если производство кухонь делает 25 заказов в месяц, а загружено на 17, свободных мест — 8. Значит, потолок бюджета — 8 × 22 500 ₽ = **180 000 ₽ в месяц** вместе с оплатой подрядчиков."},{type:"image",image:{src:i("capacity"),w:1600,h:900,alt:"Цех с работающими станками ЧПУ: мощность производства ограничивает число новых заказов",caption:"Свободная мощность цеха — верхняя граница плана продаж, а значит, и бюджета на маркетинг"}},{type:"p",text:"Если считать в обратную сторону, расчёт быстро показывает, когда маркетинг упирается не в деньги, а в производство. Тогда правильный шаг — не урезать рекламу, а поднимать чек или менять ассортимент: брать заказы, где маржа выше."},{type:"stats",items:[{v:"22 500 ₽",l:"допустимая цена клиента при чеке 300 тыс. ₽ и марже 30%"},{v:"8",l:"свободных заказов в месяц при мощности 25 и загрузке 17"},{v:"180 000 ₽",l:"потолок бюджета вместе с оплатой команды"}]},{type:"h2",id:"dlinnyj-cikl",text:"Длинный цикл сделки: сколько денег заморозится до первых договоров"},{type:"p",text:"Самая частая причина, по которой производства бросают маркетинг через два месяца, — не плохие заявки, а кассовый разрыв, о котором никто не предупредил. Реклама оплачивается сейчас, а договор — через 1–6 месяцев после первой заявки."},{type:"table",caption:"Сколько месяцев бюджета нужно заложить до первых оплат",head:["Цикл сделки","Пример","Когда ждать первых оплат","Резерв бюджета"],rows:[["До 2 недель","Кухни, шкафы, металлоизделия по готовым чертежам","В первый месяц","1 месяц"],["1–3 месяца","Металлоконструкции, ворота, модульные здания","На 2–3 месяц","2–3 месяца"],["3–6 месяцев","Станки, роботы, промышленное оборудование","На 4–6 месяц","3–4 месяца"]],note:"Ориентиры по нашим проектам. Точный срок считают по истории сделок в CRM: от первой заявки до оплаты."},{type:"p",text:"При длинном цикле оценивайте первые месяцы не по выручке, а по промежуточным шагам: число квалифицированных заявок, выезды замерщика, отправленные КП, переговоры. Если они идут по плану, договоры придут — с задержкой, равной вашему циклу сделки."},{type:"quote",text:"Есть только одно верное определение цели бизнеса — создание клиента.",author:"Питер Друкер",role:"экономист, основоположник современного менеджмента",source:"«Практика менеджмента», 1954"},{type:"form",position:2},{type:"h2",id:"sostav",text:"Что входит в маркетинговый бюджет производства"},{type:"p",text:"Ошибка, из-за которой бюджет «съезжает» на 30–50%, — считать только рекламу. Вот что должно попасть в расчёт допустимой цены клиента:"},{type:"table",caption:"Из чего складывается бюджет на привлечение клиентов",head:["Статья","Что входит","Как платить"],rows:[["Рекламный бюджет","Яндекс Директ, Avito, VK Реклама, рассылки","Напрямую в рекламную систему"],["Работа команды","Маркетолог в штате или подрядчик: настройка, оптимизация, аналитика","Фикс в месяц или процент от результата"],["Посадочные страницы","Сайт, лендинги под направления, квизы","Разово, затем доработки"],["Аналитика","Метрика, коллтрекинг, связка с CRM","Подписки на сервисы"],["Продажи","Бонус менеджеру за сделку, если он привязан к рекламным заявкам","Процент с договора"]]},{type:"p",text:"Подробно о том, почему отчёт маркетолога может показывать прибыль, а деньги на счёте не прибавляются, — в статье [«Почему лиды с ROMI 400% могут быть убыточными»](/blog/hidden-losses-behind-romi/)."},{type:"products",title:"Чем можем помочь",items:[{href:"/services/analytics/",title:"Аналитика и стратегия",text:"Посчитаем допустимую цену клиента и настроим путь от рекламы до договора в CRM"},{href:"/services/yandex-direct/",title:"Яндекс Директ под договоры",text:"Кампании, которые оптимизируются по сделкам, а не по кликам"},{href:"/#formats",title:"Форматы оплаты",text:"Фикс от 40 000 ₽ в месяц или партнёрский формат с оплатой за результат"}]},{type:"h2",id:"kontrol",text:"Как каждый месяц проверять, что бюджет работает"},{type:"p",text:"Собственнику не нужно разбираться в рекламных кабинетах. Достаточно раз в месяц смотреть на одну строку: сколько потратили на привлечение и сколько договоров и маржи это принесло."},{type:"steps",items:["**Фактическая цена клиента** = все расходы на привлечение за месяц ÷ новые договоры. Сравните с допустимой.","**Цена заявки и конверсия в договор** — если цена клиента выросла, станет видно, где проблема: реклама подорожала или отдел продаж стал хуже закрывать сделки.","**Загрузка цеха** — не превышает ли поток заказов свободную мощность. Если превышает — можно поднимать цены, а не бюджет.","**Сделки в работе** — при длинном цикле смотрите, сколько денег «в воронке»: КП, переговоры, согласования."]},{type:"image",image:{src:i("owner-tablet"),w:1600,h:900,alt:"Собственник мебельного производства проверяет показатели продаж на планшете у раскроечного станка",caption:"Раз в месяц — одна сводка: расход, заявки, договоры, маржа и загрузка цеха"}},{type:"p",text:"Если подрядчик или маркетолог не может показать эту сводку, проблема не в бюджете, а в том, что маркетинг не связан с продажами. С этого мы и начинаем любой проект — [вот как устроены этапы работы](/#process)."},{type:"h2",id:"zaklyuchenie",text:"Заключение"},{type:"list",items:["Процент от выручки — ориентир для корпораций. Производству бюджет нужно считать от маржи сделки.","Допустимая цена клиента = чек × маржинальность × доля маржи на привлечение (обычно 15–30%).","Потолок бюджета = допустимая цена клиента × свободная мощность цеха.","При длинном цикле заложите резерв на 1–4 месяца до первых оплат и оценивайте промежуточные шаги.","В расчёт входят все расходы на привлечение — реклама, команда, сайт, аналитика, бонусы продаж."]},{type:"p",text:"Если хотите, посчитаем эти цифры для вашего производства вместе: 30 минут на созвоне — и у вас будет допустимая цена клиента, план по заявкам и потолок бюджета."},{type:"form",position:3}],faq:[{q:"Сколько процентов от выручки производство должно тратить на маркетинг?",a:"Универсального процента нет. Крупные компании тратят в среднем около 7,7% выручки (Gartner, 2025), но производству точнее считать от экономики сделки: допустимая цена клиента × число новых заказов, которые может взять цех."},{q:"Как посчитать допустимую стоимость привлечения клиента?",a:"Умножьте средний чек на маржинальность и на долю маржи, которую готовы отдать на привлечение, — обычно 15–30%. Например, при чеке 300 000 ₽, марже 30% и доле 25% допустимая цена клиента — 22 500 ₽."},{q:"Входит ли оплата маркетолога или агентства в бюджет на маркетинг?",a:"Да. В допустимую цену клиента должны поместиться все расходы на привлечение: рекламный бюджет, оплата команды, сайт и посадочные страницы, сервисы аналитики, бонусы менеджерам за сделки."},{q:"Когда маркетинг производства начинает окупаться?",a:"Зависит от цикла сделки. При цикле до двух недель первые оплаты приходят в первый месяц, при цикле 3–6 месяцев — на 4–6 месяц. Поэтому бюджет нужно закладывать с резервом на этот срок."},{q:"Что делать, если реклама не окупается при любом бюджете?",a:"Проверить три вещи: маржу (не продаёте ли вы в минус после всех расходов), конверсию заявки в договор (не теряет ли отдел продаж обращения) и чек (не стоит ли сместиться к более маржинальным заказам). Обычно проблема в одной из них, а не в рекламе."},{q:"Можно ли платить за маркетинг только за результат?",a:"Да, если в компании есть CRM и прозрачные данные по сделкам. В партнёрском формате вы оплачиваете рекламный бюджет, а команда получает процент с заключённых договоров."}],sources:[{title:"Gartner 2025 CMO Spend Survey Reveals Marketing Budgets Have Flatlined at 7.7% of Overall Company Revenue",publisher:"Gartner, 12 мая 2025",url:"https://www.gartner.com/en/newsroom/press-releases/2025-05-12-gartner-2025-cmo-spend-survey-reveals-marketing-budgets-have-flatlined-at-seven-percent-of-overall-company-revenue"},{title:"CAC (Customer Acquisition Cost) в маркетинге: что это, формула расчёта стоимости привлечения клиента",publisher:"Яндекс для бизнеса",url:"https://b2b.yandex.ru/adv/edu/materials/cac"},{title:"Peter F. Drucker, «The Practice of Management» (1954)",publisher:"Wikiquote",url:"https://en.wikiquote.org/wiki/Peter_Drucker"},{title:"Кейс: кухни на заказ в Ростове-на-Дону — 99 клиентов за 1,5 года",publisher:"Квалити",url:"https://kvaliti-team.ru/cases/kitchens-rostov/"}],comments:[{name:"Тимур Кисиев",role:"основатель «Квалити», автор статьи",date:"2026-10-16",team:!0,text:"Дополню про долю маржи на привлечение. Если не знаете, с какой цифры начать, берите 20% и смотрите на первые 2–3 месяца: при хорошей конверсии отдела продаж её можно поднимать, при слабой — сначала разбираться с обработкой заявок, а не с рекламой."}]},a="/blog/shtatnyj-marketolog-ili-autsorsing",r={slug:"shtatnyj-marketolog-ili-autsorsing",hub:"upravlenie-marketingom",published:"2026-10-16",kind:"article",label:"Гайд",tags:["аутсорсинг маркетинга","маркетолог для производства","для собственника","управление"],title:"Штатный маркетолог или команда на аутсорсе: сколько каждый вариант стоит производству за год",seoTitle:"Штатный маркетолог или аутсорсинг маркетинга: сравнение затрат за год",description:"Сравниваем полную стоимость штатного маркетолога и команды на аутсорсе для производства: зарплаты по hh.ru, страховые взносы 2026, найм, сервисы и риски. Таблицы и расчёт за 12 месяцев.",sub:"Зарплата в вакансии — меньше половины реальной стоимости. Посчитали полную цену штатного маркетолога для производства за год и сравнили с командой на аутсорсе — с налогами, наймом и временем на вход в работу.",meta:"9 минут чтения",href:"/blog/shtatnyj-marketolog-ili-autsorsing/",cover:`${a}/hero.webp`,hero:{src:`${a}/hero.webp`,w:1600,h:900,alt:"Уставший маркетолог поздно вечером один работает за тремя мониторами в офисе производства, за окном — цех"},shortAnswer:"Штатный маркетолог с зарплатой 120 000 ₽ на руки обходится производству в 2,1–2,5 млн ₽ в год: зарплата, страховые взносы, найм, сервисы и 2–3 месяца на вход в работу. Команда на аутсорсе — от 480 000 ₽ в год за работу и даёт сразу несколько специалистов: директолога, аналитика, дизайнера. Штат выгоднее, когда маркетинга много и он завязан на продукт: выставки, каталоги, дилерская сеть. Для запуска и роста заявок из интернета быстрее и дешевле команда на аутсорсе — или связка «штатный маркетинг-менеджер + подрядчик».",cases:["orion","metal-factory-two-landings","kitchens-rostov"],body:[{type:"h2",id:"zarplata",text:"Сколько просит маркетолог для производства"},{type:"p",text:"Мы посмотрели 97 вакансий со словами «маркетолог» и «производство» с указанной зарплатой на hh.ru за последние 30 дней (выборка на 16 октября 2026 года, вся Россия). Картина такая:"},{type:"stats",items:[{v:"80–150 тыс. ₽",l:"на руки — большинство предложений"},{v:"от 130–150 тыс. ₽",l:"B2B-маркетолог на производство в Москве"},{v:"70–100 тыс. ₽",l:"регионы, без опыта в B2B"}]},{type:"p",text:"Для расчёта возьмём середину — **120 000 ₽ на руки**. Это специалист, который знает рекламу и аналитику, но не директолог, не дизайнер и не разработчик сайта одновременно."},{type:"image",image:{src:`${a}/interview.webp`,w:1600,h:900,alt:"Собственник производства проводит собеседование с кандидатом на должность маркетолога",caption:"Найм маркетолога в производство занимает в среднем 1–2 месяца — и это ещё не начало работы"}},{type:"h2",id:"polnaya-stoimost",text:"Полная стоимость штатного маркетолога за год"},{type:"p",text:"Зарплата «на руки» — только часть расходов. Работодатель платит НДФЛ 13% и страховые взносы. С 2026 года льготный тариф 15% остался не у всех малых предприятий, но для МСП в обрабатывающих производствах действует пониженная ставка: **30% до 1,5 МРОТ и 7,6% сверх** (1,5 МРОТ в 2026 году — 40 639,5 ₽)."},{type:"table",caption:"Штатный маркетолог с зарплатой 120 000 ₽ на руки: расходы за 12 месяцев",head:["Статья расходов","Общий тариф взносов","МСП-производство (льготный тариф)","Комментарий"],rows:[["Зарплата до НДФЛ","1 655 172 ₽","1 655 172 ₽","137 931 ₽ в месяц"],["Страховые взносы","496 552 ₽","235 032 ₽","30% или 30% + 7,6%"],["Найм","60 000–150 000 ₽","60 000–150 000 ₽","кадровое агентство или время собственника"],["Сервисы и обучение","60 000–120 000 ₽","60 000–120 000 ₽","коллтрекинг, аналитика, сервисы для креативов"],["Рабочее место","60 000–100 000 ₽","60 000–100 000 ₽","ноутбук, лицензии, доля аренды"],["**Итого за год**","**≈ 2,3–2,5 млн ₽**","**≈ 2,1–2,3 млн ₽**","без рекламного бюджета"]],highlight:2,note:"Найм, сервисы и рабочее место — ориентиры по нашим проектам. Тариф взносов уточните у бухгалтера: льгота зависит от основного ОКВЭД и статуса МСП."},{type:"key",text:"Даже на льготном тарифе маркетолог с зарплатой 120 000 ₽ на руки стоит производству **около 2 млн ₽ в год** — до того, как потрачен первый рубль на рекламу."},{type:"image",image:{src:`${a}/iceberg.webp`,w:1600,h:900,alt:"Объёмная иллюстрация айсберга в разрезе: над водой небольшая вершина, под водой — этажи с ноутбуками, документами, песочными часами и креслом для собеседований",caption:"Зарплата в вакансии — верхушка. Взносы, найм, сервисы и время на вход в работу скрыты под водой"}},{type:"h2",id:"skrytye",text:"Расходы, которых нет в смете"},{type:"p",text:"Есть три расхода, которые не видны в бухгалтерии, но стоят денег больше, чем взносы."},{type:"steps",items:["**Время до результата.** Найм — 1–2 месяца, вход в работу — ещё 2–3. Первые полгода маркетолог стоит денег, а заявок почти не приносит.","**Подрядчики всё равно нужны.** Один человек не сделает сайт, креативы, рекламу и аналитику на уровне профильных специалистов. Дизайнер и разработчик — отдельный бюджет.","**Риск ухода.** Если маркетолог уходит через год, вместе с ним уходят настройки, доступы и понимание, что работало. Найм начинается заново."]},{type:"quote",text:"Если каждый из нас нанимает людей ниже себя, мы станем компанией карликов. Если нанимаем людей сильнее себя — компанией гигантов.",author:"Дэвид Огилви",role:"Основатель агентства Ogilvy & Mather",source:"«Огилви о рекламе», 1983"},{type:"p",text:"Для производства с выручкой 3–30 млн ₽ в месяц нанять «гиганта» в штат обычно не по карману: сильный руководитель маркетинга в B2B стоит от 200–300 тыс. ₽ на руки. Поэтому часть компаний покупает не человека, а результат команды."},{type:"form",position:1},{type:"h2",id:"autsors",text:"Что даёт команда на аутсорсе и сколько стоит"},{type:"p",text:"Команда на аутсорсе — это не «маркетолог на удалёнке», а несколько специалистов под одну задачу: руководитель проекта, директолог, аналитик, дизайнер, при необходимости разработчик и специалист по рассылкам. Вы платите за работу команды и отдельно — рекламный бюджет."},{type:"image",image:{src:`${a}/team.webp`,w:1600,h:900,alt:"Собственник производства на видеосозвоне с командой маркетологов на аутсорсе, рядом на экране — дашборд сделок",caption:"На аутсорсе вы получаете не одного человека, а набор ролей — и общий отчёт по сделкам"}},{type:"table",caption:"Штатный маркетолог и команда на аутсорсе: сравнение для производства",head:["Критерий","Штатный маркетолог","Команда на аутсорсе","Связка: маркетинг-менеджер + подрядчик"],rows:[["Стоимость за год (без рекламы)","≈ 2,1–2,5 млн ₽","от 480 000 ₽","≈ 1,9–2,5 млн ₽"],["Сколько специалистов","1","3–6 ролей","1 + команда"],["Старт работы","через 2–4 месяца","запуск за 5 дней","через 1–2 месяца"],["Знание продукта","глубокое","нужно погружение","глубокое"],["Риск ухода специалиста","высокий","замена внутри команды","средний"],["Оплата за результат","премия по KPI","возможна: % с договоров","на стороне подрядчика"],["Кому подходит","много офлайн-маркетинга, выставки, дилеры","нужен поток заявок из интернета","выручка от 30 млн ₽ в месяц"]],highlight:2,note:"Стоимость аутсорса — фиксированный формат работы команды Квалити. У других подрядчиков цены и состав команды отличаются."},{type:"p",text:"Справедливости ради: аутсорс подходит не всем. Если маркетинг производства — это выставки, каталоги, работа с дилерами и тендерами, нужен человек внутри компании. По данным Gartner, 39% директоров по маркетингу крупных компаний в 2025 году планировали сократить бюджеты на агентства — часть задач они забирают в штат. Для производства среднего размера выгоднее связка: менеджер по маркетингу внутри + подрядчик на рекламу, сайт и аналитику."},{type:"h2",id:"kak-vybrat",text:"Как выбрать: пять вопросов собственнику"},{type:"table",caption:"Подсказка для выбора формата",head:["Вопрос","Если «да»","Если «нет»"],rows:[["Нужны заявки из интернета в ближайшие 1–2 месяца?","аутсорс","можно нанимать в штат"],["Маркетинг — это в основном выставки, каталоги, дилеры?","штат или связка","аутсорс"],["Бюджет на маркетинг (без рекламы) меньше 150 000 ₽ в месяц?","аутсорс","рассмотрите связку"],["Есть кто-то, кто будет ставить задачи и проверять маркетолога?","штат возможен","аутсорс с отчётностью"],["Хотите платить за результат, а не за процесс?","аутсорс с % от договоров","любой формат"]]},{type:"image",image:{src:"/blog/orion/bitrix-crm.webp",w:1672,h:941,alt:"Воронка сделок в CRM мебельной фабрики: заявки из рекламы распределены по этапам продаж",caption:"Мебельная фабрика «Орион»: заявки из рекламы в CRM клиента — собственник видит каждую сделку"}},{type:"p",text:"Какой бы формат вы ни выбрали, требуйте одного: **видеть путь от рекламы до договора**. Если подрядчик или штатный маркетолог отчитывается кликами и заявками, а не договорами и выручкой, вы платите за процесс. Как считать результат в деньгах, разобрали в статье [«Сколько производству тратить на маркетинг»](/blog/skolko-tratit-na-marketing-proizvodstvu/)."},{type:"form",position:2},{type:"h2",id:"proverka",text:"Как проверить подрядчика за 30 минут"},{type:"image",image:{src:`${a}/owner-report.webp`,w:1600,h:900,alt:"Собственник производства изучает распечатанный ежемесячный отчёт с графиками продаж и воронкой, на ноутбуке открыта CRM",caption:"Отчёт подрядчика должен отвечать на вопрос собственника: сколько договоров и денег принёс маркетинг"}},{type:"steps",items:["**Попросите кейс в вашей или соседней нише** — с цифрами расхода, заявок и договоров, а не только «рост трафика».","**Спросите, как будут считать результат.** Правильный ответ — связка рекламы с CRM и отчёт в договорах.","**Уточните, кто конкретно будет работать** над проектом и сколько у него ещё клиентов.","**Проверьте условия выхода:** доступы к рекламным кабинетам и аналитике должны быть оформлены на вашу компанию.","**Предложите часть оплаты за результат.** Подрядчик, уверенный в себе, согласится обсуждать процент с договоров."]},{type:"products",title:"Решения по теме",items:[{href:"/#formats",title:"Форматы сотрудничества",text:"Фикс от 40 000 ₽ в месяц или партнёрский формат с оплатой за договоры"},{href:"/services/analytics/",title:"Аналитика и стратегия",text:"Свяжем рекламу с CRM, чтобы видеть стоимость каждого договора"},{href:"/cases/",title:"Кейсы команды",text:"Расход, заявки, договоры и выручка по реальным проектам"}]},{type:"h2",id:"itog",text:"Итог"},{type:"list",items:["Штатный маркетолог с зарплатой 120 000 ₽ на руки обходится производству в 2,1–2,5 млн ₽ в год без рекламы.","Первые 3–6 месяцев уходят на найм и вход в работу — заявок в это время почти нет.","Команда на аутсорсе стоит от 480 000 ₽ в год и даёт сразу несколько специалистов.","Штат выгоднее, когда маркетинг в основном офлайн: выставки, дилеры, каталоги.","В любом формате требуйте отчёт в договорах и выручке, а доступы оформляйте на свою компанию."]},{type:"form",position:3}],faq:[{q:"Что дешевле: штатный маркетолог или аутсорсинг маркетинга?",a:"Для производства с выручкой до 30 млн ₽ в месяц обычно дешевле аутсорс: штатный маркетолог с зарплатой 120 000 ₽ на руки стоит около 2,1–2,5 млн ₽ в год с налогами, наймом и сервисами, а команда на аутсорсе — от 480 000 ₽ в год за работу. Рекламный бюджет в обоих случаях оплачивается отдельно."},{q:"Сколько стоит маркетолог для производства в 2026 году?",a:"По вакансиям hh.ru на октябрь 2026 года большинство предложений — 80–150 тыс. ₽ на руки, B2B-маркетологи на производство в Москве — от 130–150 тыс. ₽. С НДФЛ и страховыми взносами работодатель платит на 30–50% больше суммы на руки."},{q:"Какие страховые взносы платит производство за маркетолога?",a:"По общему тарифу — 30% в пределах базы. МСП в обрабатывающих производствах из льготного перечня платят 30% с выплат до 1,5 МРОТ (40 639,5 ₽ в 2026 году) и 7,6% сверх. Точный тариф зависит от основного ОКВЭД — уточните у бухгалтера."},{q:"Когда лучше взять маркетолога в штат?",a:"Когда маркетинга много и он завязан на продукт и офлайн: выставки, каталоги, работа с дилерами и тендерами, а в компании есть руководитель, который ставит задачи и проверяет результат. Для запуска заявок из интернета быстрее команда на аутсорсе."},{q:"Можно ли платить подрядчику по маркетингу за результат?",a:"Да. В партнёрском формате вы оплачиваете рекламный бюджет, а подрядчик получает процент с заключённых договоров. Для этого нужен общий доступ к CRM и прозрачные данные по сделкам."},{q:"Как быстро команда на аутсорсе начинает работу?",a:"В Квалити подготовка к запуску Яндекс Директа занимает до 5 дней, первые заявки приходят на 3–5 день после старта рекламы. На плановые показатели проект обычно выходит ко второму месяцу."}],sources:[{title:"Вакансии «маркетолог производство» с указанной зарплатой за 30 дней, вся Россия",publisher:"hh.ru, выборка на 16.10.2026",url:"https://hh.ru/search/vacancy?text=%D0%BC%D0%B0%D1%80%D0%BA%D0%B5%D1%82%D0%BE%D0%BB%D0%BE%D0%B3+%D0%BF%D1%80%D0%BE%D0%B8%D0%B7%D0%B2%D0%BE%D0%B4%D1%81%D1%82%D0%B2%D0%BE&area=113&only_with_salary=true&search_period=30"},{title:"Страховые взносы‑2026: конец универсальной льготы для МСП и новые ставки",publisher:"Клерк.ру",url:"https://www.klerk.ru/buh/articles/712742/"},{title:"Gartner 2025 CMO Spend Survey Reveals Marketing Budgets Have Flatlined at 7.7% of Overall Company Revenue",publisher:"Gartner, 12 мая 2025",url:"https://www.gartner.com/en/newsroom/press-releases/2025-05-12-gartner-2025-cmo-spend-survey-reveals-marketing-budgets-have-flatlined-at-seven-percent-of-overall-company-revenue"},{title:"Считаем, кто выгоднее бизнесу: штатный маркетолог или агентство",publisher:"Cossa, 2023",url:"https://www.cossa.ru/itagency/323221/"},{title:"David Ogilvy — цитаты",publisher:"Wikiquote («Ogilvy on Advertising», с. 47)",url:"https://en.wikiquote.org/wiki/David_Ogilvy"}],comments:[{name:"Тимур Кисиев",role:"основатель «Квалити», автор статьи",date:"2026-10-16",team:!0,text:"Частый вопрос на встречах: «а если взять маркетолога и дать ему вашу команду в подрядчики?». Это и есть связка из таблицы — и для производств с выручкой от 30 млн ₽ в месяц она часто лучшая. Главное условие: один человек внутри отвечает за результат и видит путь от заявки до договора, а не только отчёт подрядчика."}]},o="zavisimost-ot-krupnyh-klientov",p=t=>`/blog/${o}/${t}.webp`,l={slug:o,href:`/blog/${o}/`,hub:"rost-prodazh",kind:"article",label:"Гайд",published:"2026-10-18",tags:["рост продаж","новые клиенты","сарафанное радио","производство"],title:"Производство держится на 2–3 клиентах: как снизить зависимость, пока крупный заказчик не ушёл",seoTitle:"Зависимость от одного клиента: что делать производству",description:"Как собственнику производства оценить зависимость от крупных клиентов и сарафанного радио, посчитать риск в деньгах и за 90 дней выстроить поток новых заказчиков. С примерами из проектов.",sub:"Когда один заказчик даёт треть выручки, его уход — это не «неприятность», а кассовый разрыв. Разбираем, как посчитать риск за 10 минут и какие каналы дают производству новых клиентов без сарафана.",meta:"11 минут чтения · рост продаж",cover:p("hero"),hero:{src:p("hero"),w:1600,h:900,alt:"Собственник производства металлоконструкций задумчиво смотрит на полупустую доску с графиком заказов в цехе",caption:"Пока крупный клиент платит, зависимость незаметна. Её видно, когда в графике цеха появляются пустые недели"},shortAnswer:"Зависимость от клиента становится опасной, когда один заказчик даёт больше 25% выручки или три крупнейших — больше половины. Посчитайте эти доли по оплатам за 12 месяцев и переведите риск в деньги: сколько маржи вы потеряете, если крупнейший клиент уйдёт, при тех же аренде, зарплатах и кредитах. Снижать зависимость нужно не отказом от крупных клиентов, а управляемым потоком новых: 1–2 канала с горячим спросом или прямым выходом на ЛПР, посадочные под сегменты и план «новые клиенты дают X% выручки через 90 дней».",cases:["orion","metal-factory-two-landings","kitchens-rostov"],body:[{type:"p",text:"У многих производств одна и та же история: завод или цех построили на нескольких крупных заказчиках и рекомендациях. Годами это работает — заказы есть, маркетинг не нужен. А потом крупный клиент меняет поставщика, урезает объёмы или уходит в отсрочку на 90 дней. И выясняется, что других клиентов взять неоткуда: сайт устарел, рекламы не было, отдел продаж умеет только принимать входящие."},{type:"p",text:"Ниже — как оценить, насколько ваш бизнес зависит от нескольких клиентов, перевести этот риск в рубли и выстроить поток новых заказчиков, не теряя текущих."},{type:"h2",id:"risk",text:"Почему 2–3 крупных клиента — это риск, а не стабильность"},{type:"p",text:"Крупный клиент приятен: большие объёмы, понятные заказы, не нужно искать. Но у такой стабильности три скрытые цены."},{type:"steps",items:["**Уход клиента бьёт по марже сильнее, чем по выручке.** Выручка падает, а аренда, зарплаты, лизинг станков и кредиты остаются прежними.","**Клиент диктует условия.** Тот, без кого вы не сможете, со временем просит скидку, отсрочку платежа и приоритет в графике — и вы соглашаетесь.","**Бизнес дешевле стоит.** Покупатели, инвесторы и банки смотрят на концентрацию выручки. По оценке аналитиков Willamette Management Associates, потеря клиента, который даёт 10% выручки, снижает стоимость компании примерно на 11,6% — и чем выше доля, тем сильнее падение."]},{type:"p",text:"Порог в 10% выбран не случайно. Международный стандарт отчётности МСФО (IFRS) 8 требует раскрывать в отчётности факт, что выручка от одного внешнего покупателя составляет 10% и более. Для крупных компаний это сигнал риска, который обязаны показать инвесторам."},{type:"quote",text:"Концентрация клиентов — частое явление для частных компаний.",author:"Дж. Маккей Халверсон",role:"аналитик по оценке бизнеса, Willamette Management Associates",source:"Measuring Customer Concentration Risk, 2026",sourceUrl:"https://www.insights.willamette.com/resources/perspectives-insights/perspectives-2026-07/measuring-customer-concentration-risk.html"},{type:"image",image:{src:p("handshake"),w:1600,h:900,alt:"Объёмная иллюстрация: платформа с миниатюрным цехом накренилась на одной стальной колонне, рядом лежат неустановленные зелёные опоры",caption:"Когда весь вес держит одна опора, устойчивость зависит от неё одной"}},{type:"h2",id:"proverka",text:"Проверка за 10 минут: насколько вы зависите от крупных клиентов"},{type:"p",text:"Откройте выгрузку оплат за последние 12 месяцев — из 1С, банка или CRM. Нужны две цифры: доля крупнейшего клиента и доля трёх крупнейших в общей выручке."},{type:"table",caption:"Ориентиры по концентрации выручки",head:["Доля крупнейшего клиента","Доля трёх крупнейших","Что это значит","Что делать"],rows:[["до 10%","до 30%","Выручка распределена","Держать текущий поток новых клиентов"],["10–25%","30–50%","Заметная зависимость","Запустить 1 канал привлечения и следить за долей раз в квартал"],["25–40%","50–70%","Зона риска: уход клиента — кассовый разрыв","План на 90 дней: 1–2 канала, посадочные под сегменты"],["больше 40%","больше 70%","Критично: клиент фактически управляет бизнесом","Новые клиенты — главная задача собственника на ближайший квартал"]],highlight:2,note:"Пороги — наши ориентиры по проектам с производствами. Для отраслей с длинными контрактами (госзаказ, поставки в сети) допустимая концентрация выше, но и последствия ухода клиента тяжелее."},{type:"p",text:"Теперь переведите долю в деньги. Условный пример: выручка производства — 10 млн ₽ в месяц, крупнейший клиент даёт 3 млн ₽ (30%), маржа — 30%. Если он уходит, вы теряете **900 000 ₽ маржи в месяц**, а постоянные расходы не меняются. Для многих производств это разница между прибылью и убытком."},{type:"stats",items:[{v:"30%",l:"доля крупнейшего клиента в выручке 10 млн ₽"},{v:"900 000 ₽",l:"маржи в месяц уходит вместе с ним"},{v:"4–6 месяцев",l:"нужно, чтобы с нуля заменить его новыми клиентами"}]},{type:"key",title:"Главное",text:"Новых клиентов нужно искать, пока крупный заказчик ещё платит. Когда он ушёл, на запуск маркетинга уже нет ни денег, ни времени."},{type:"h2",id:"sarafan",text:"Почему сарафанное радио не спасёт"},{type:"p",text:"Рекомендации — лучший канал по качеству клиента: он уже доверяет и редко торгуется. Проблема в том, что сарафаном нельзя управлять. Вы не можете попросить у него 10 заказов к следующему месяцу."},{type:"table",caption:"Сарафанное радио и управляемый поток клиентов",head:["Критерий","Сарафанное радио и связи","Управляемый поток"],rows:[["Сколько клиентов придёт в следующем месяце","Неизвестно","Прогноз по бюджету и цене заявки"],["Можно ли увеличить, когда цех простаивает","Нет","Да: увеличить бюджет или подключить канал"],["Кто приходит","Похожие на текущих клиентов, из того же круга","Новые сегменты и регионы"],["Стоимость клиента","Кажется бесплатной, но часто это скидки «по дружбе»","Известна и сравнивается с маржой"],["Зависит от собственника","Полностью: его связи и репутация","Работает без его личного участия"]],highlight:2},{type:"p",text:"Сарафан не нужно заменять — его нужно дополнить каналом, которым можно управлять. Об экономике такого канала — сколько можно платить за нового клиента при вашей марже — мы подробно писали в статье [«Сколько производству тратить на маркетинг»](/blog/skolko-tratit-na-marketing-proizvodstvu/)."},{type:"form",position:1},{type:"h2",id:"kanaly",text:"Пять каналов, через которые производства находят новых клиентов"},{type:"p",text:"Выбор канала зависит от того, ищут ли ваш продукт сами клиенты. Если ищут — работает реклама на горячий спрос. Если решение принимает узкий круг людей в компаниях — нужен прямой выход на них."},{type:"table",caption:"Каналы привлечения новых клиентов для производства",head:["Канал","Когда работает","Первые заявки","Пример из наших проектов"],rows:[["Яндекс Директ на горячий спрос","Продукт ищут в поиске: кухни, металлоконструкции, оборудование","На 3–5 день после старта","Кухни: 890 заявок по 1 220 ₽, 99 договоров"],["Посадочные под сегменты","Есть 2–3 направления с разными клиентами","Вместе с рекламой","Завод металлоизделий: конверсия выросла в 2,5 раза"],["Прямой выход на ЛПР","B2B, решение принимает конкретный человек: снабжение, главный инженер","Через 1–2 недели","Орион: 15+ B2B-запросов через обзвон по ЛПР"],["Avito","Клиенты ищут исполнителя или товар в объявлениях","В первую неделю","Комплекты, услуги монтажа и изготовления"],["Дилеры и оптовые покупатели","Нужен выход в регионы без своих офисов","Через 1–3 месяца","Подробнее — в разделе [«Новые рынки»](/blog/rynki-sbyta/)"]],highlight:1},{type:"image",image:{src:p("sales-call"),w:1600,h:900,alt:"Менеджер по продажам производства говорит с новым клиентом через гарнитуру и делает пометки, на мониторе — чертёж детали",caption:"Новый клиент начинается не с рекламы, а с того, как быстро и предметно ему ответили"}},{type:"p",text:"Любой канал даст результат, только если отдел продаж готов к новым клиентам. На заводе металлоизделий, который 20 лет продавал через дилеров и связи владельца, мы начали с простого: заявка попадает в CRM, менеджер отвечает в среднем **за 25 минут** вместо нескольких часов, все звонки записываются. Без этого реклама просто сжигала бы бюджет."},{type:"quote",text:"Поскольку цель бизнеса — создание клиента, у предприятия есть две и только две основные функции: маркетинг и инновации.",author:"Питер Друкер",role:"экономист, основоположник современного менеджмента",source:"«Практика менеджмента», 1954"},{type:"h2",id:"plan",text:"План на 90 дней: как снизить зависимость, не теряя текущих клиентов"},{type:"steps",items:["**Недели 1–2. Цифры.** Доля крупнейшего клиента и топ-3, маржа по направлениям, допустимая цена нового клиента. Выпишите 5–10 лучших клиентов за 2 года и ответьте: какие у них общие черты — отрасль, размер, регион, кто принимал решение.","**Недели 3–4. Сегменты и посадочные.** Под каждый сегмент «двойников» лучших клиентов — своя страница с понятным предложением, фото производства, сроками и формой с прикреплением чертежей.","**Месяц 2. Запуск 1–2 каналов.** Горячий спрос — Директ и Avito, узкий круг ЛПР — прямой выход через сообщения, письма и звонки. Каждая заявка — в CRM, ответ — в течение часа.","**Месяц 3. Оптимизация по договорам.** Отключаем то, что даёт заявки без сделок, усиливаем то, что приводит договоры. Ставим цель: новые клиенты дают 15–20% выручки к концу полугода."]},{type:"image",image:{src:p("balance"),w:1600,h:900,alt:"Объёмная иллюстрация: платформа с работающим миниатюрным цехом устойчиво стоит на пяти опорах — одной стальной и четырёх зелёных",caption:"Цель — не отказаться от крупных клиентов, а сделать так, чтобы выручка стояла на нескольких опорах"}},{type:"key",title:"Важно",text:"Не отказывайтесь от крупного клиента и не поднимайте ему цены, пока новый поток не заработал. Задача — снизить его **долю**, а не его объём."},{type:"form",position:2},{type:"h2",id:"keisy",text:"Как это выглядело в наших проектах"},{type:"p",text:"**Мебельная фабрика «Орион», Уфа.** Компания жила только на рекомендациях — ни сайта, ни рекламы. За 4 месяца сделали сайт и квиз-воронку, запустили Яндекс Директ по Уфе и соседним регионам, параллельно вышли на B2B-клиентов обзвоном по ЛПР. Итог: **61 обращение, 12 договоров и 1,5+ млн ₽ продаж**, плюс 15+ B2B-запросов в переговорах. [Полный разбор кейса](/blog/orion-yandex-direct/)."},{type:"image",image:{src:p("workshop"),w:1600,h:900,alt:"Цех мебельного производства: раскрой плит и сборка корпусов, сотрудники за работой",caption:"Мебельному производству новые клиенты нужны, чтобы цех был загружен ровно, а не от заказа к заказу"}},{type:"p",text:"**Завод металлоизделий.** 20 лет все продажи шли офлайн — через дилеров и связи владельца, не было плана заявок и прогноза загрузки. Сделали два лендинга под главные услуги вместо одного общего сайта, запустили контекстную рекламу, внедрили Битрикс24 и IP-телефонию. Конверсия сайта выросла **в 2,5 раза**, а собственник теперь видит в онлайне заявки, расходы и закрытые сделки. [Разбор кейса](/cases/metal-factory-two-landings/)."},{type:"products",title:"Чем можем помочь",items:[{href:"/services/yandex-direct/",title:"Яндекс Директ под договоры",text:"Горячий спрос: клиенты, которые уже ищут ваш продукт"},{href:"/services/messenger-outreach/",title:"Прямой выход на ЛПР",text:"Адресные сообщения и звонки тем, кто принимает решение о закупке"},{href:"/services/sites/",title:"Посадочные под сегменты",text:"Отдельные страницы под направления — как на заводе металлоизделий"}]},{type:"h2",id:"zaklyuchenie",text:"Заключение"},{type:"list",items:["Если один клиент даёт больше 25% выручки или три — больше половины, вы в зоне риска.","Переведите долю в маржу: сколько денег уйдёт вместе с клиентом при тех же постоянных расходах.","Сарафан — хороший канал, но им нельзя управлять. Его нужно дополнить потоком, который масштабируется бюджетом.","Выбирайте канал по тому, как вас ищут: горячий спрос — реклама, узкий круг ЛПР — прямой выход.","Начинайте, пока крупный клиент ещё платит: на замену ему нужно 4–6 месяцев."]},{type:"p",text:"Если хотите, разберём ваш случай: посчитаем долю крупных клиентов, допустимую цену нового и подберём 1–2 канала под ваш продукт. 30 минут на созвоне, без обязательств."},{type:"form",position:3}],faq:[{q:"Какая доля одного клиента в выручке считается опасной?",a:"Мы ориентируемся на 25% для крупнейшего клиента и 50% для трёх крупнейших: выше этих порогов уход клиента приводит к кассовому разрыву. Для сравнения, стандарт МСФО (IFRS) 8 требует раскрывать в отчётности каждого покупателя, который даёт 10% выручки и больше."},{q:"Как быстро можно заменить ушедшего крупного клиента?",a:"С нуля — обычно за 4–6 месяцев: 1–2 месяца на запуск каналов и отладку продаж, ещё 2–4 месяца, чтобы новые клиенты дали сопоставимую выручку. Поэтому начинать лучше, пока крупный клиент ещё работает с вами."},{q:"Что делать, если все клиенты приходят по рекомендациям?",a:"Сохранить рекомендации и добавить управляемый канал: рекламу на горячий спрос или прямой выход на ЛПР в похожих компаниях. Сначала выпишите общие черты лучших клиентов — это и будет портрет для нового канала."},{q:"Какой канал привлечения выбрать производству?",a:"Если ваш продукт ищут в интернете — Яндекс Директ и Avito: первые заявки приходят через 3–5 дней. Если решение принимает узкий круг людей в компаниях — прямой выход на ЛПР через сообщения, письма и звонки. Дилеры и оптовики подходят для выхода в новые регионы."},{q:"Нужно ли отказываться от крупного клиента, чтобы снизить зависимость?",a:"Нет. Задача — снизить его долю в выручке за счёт новых клиентов, а не его объём. Отказываться от крупного заказчика или резко менять ему условия до того, как заработал новый поток, рискованно."},{q:"Сколько стоит выстроить поток новых клиентов?",a:"Работа команды Квалити в фиксированном формате — от 40 000 ₽ в месяц плюс рекламный бюджет. Допустимую цену клиента считаем от вашей маржи, чтобы реклама окупалась на договорах, а не на заявках."}],sources:[{title:"Measuring Customer Concentration Risk",publisher:"Willamette Management Associates, Perspectives, июль 2026",url:"https://www.insights.willamette.com/resources/perspectives-insights/perspectives-2026-07/measuring-customer-concentration-risk.html"},{title:"IFRS 8 — entity-wide disclosures (раскрытие информации о крупных покупателях)",publisher:"Grant Thornton",url:"https://www.grantthornton.global/en/insights/articles/ifrs-8/ifrs-8-entity-wide-disclosures/"},{title:"Peter F. Drucker, «The Practice of Management» (1954)",publisher:"Wikiquote",url:"https://en.wikiquote.org/wiki/Peter_Drucker"},{title:"Кейс: мебельная фабрика «Орион» — 12 договоров и 1,5+ млн ₽ из Яндекс Директ",publisher:"Квалити",url:"https://kvaliti-team.ru/blog/orion-yandex-direct/"},{title:"Кейс: завод металлоизделий — два лендинга, CRM и рост конверсии в 2,5 раза",publisher:"Квалити",url:"https://kvaliti-team.ru/cases/metal-factory-two-landings/"}],comments:[{name:"Тимур Кисиев",role:"основатель «Квалити», автор статьи",date:"2026-10-18",team:!0,text:"Самое частое, что слышу на встречах: «у нас и так всё загружено, маркетинг потом». Посчитайте долю двух главных клиентов. Если она больше половины — «потом» может наступить в тот день, когда один из них не продлит договор."}]},n="kak-najti-dilerov-dlya-proizvodstva",y=t=>`/blog/${n}/${t}.webp`,h={slug:n,href:`/blog/${n}/`,hub:"rynki-sbyta",kind:"article",label:"Гайд",published:"2026-10-25",tags:["дилеры","новые рынки","регионы","производство"],title:"Как производству найти дилеров в регионах: 6 каналов, расчёт скидки и ошибки в договоре",seoTitle:"Как найти дилеров для своей продукции: гайд для производства",description:"Где производству искать дилеров и оптовиков в регионах, какую скидку выдержит ваша маржа, что предложить дилеру и какие условия договора запрещает закон. Таблицы, расчёт и план на 90 дней.",sub:"Объявление «ищем дилеров» приводит случайных людей. Разбираем, как найти тех, кто будет продавать ваш продукт в регионе: кого искать, сколько маржи отдать и что нельзя писать в договоре.",meta:"16 минут чтения · новые рынки",cover:y("hero"),hero:{src:y("hero"),w:1600,h:900,alt:"Собственник производства у большой карты России на стене цеха отмечает зелёными флажками регионы для поиска дилеров",caption:"Дилерская сеть начинается не с объявления, а с решения, в каких регионах и через кого вы хотите продавать"},shortAnswer:"Дилеров для производства находят не объявлением «ищем дилеров», а целевым поиском. Выберите 3–5 регионов, откуда уже приходят заявки или где работают похожие компании, соберите базу магазинов, монтажных компаний и оптовиков и выйдите напрямую на собственников. Параллельно включите рекламу «станьте дилером» по этим регионам и отраслевые выставки. До первого звонка посчитайте, какую дилерскую скидку выдержит ваша маржа, и подготовьте понятную программу: скидка, пробная партия, территория, передача заявок из региона. Начинайте с 2–3 дилеров и считайте не подписанные договоры, а повторные заказы через 2–3 месяца.",cases:["metal-factory-two-landings","orion","industrial-robots"],body:[{type:"p",text:"Когда производство упирается в свой город, собственник обычно думает о двух вариантах: открывать филиалы или искать дилеров. Филиалы — это аренда, склад и люди в каждом регионе. Дилеры выглядят проще: они уже знают местный рынок, у них есть магазин, клиенты и монтажники. Остаётся их найти."},{type:"p",text:"На практике путь часто выглядит так: объявление «ищем дилеров» на сайте и на площадках, десяток звонков от случайных людей, два договора, которые не приносят ни одного заказа. Ниже — как сделать по-другому: посчитать экономику до поиска, искать тех, у кого уже есть ваши клиенты, и предложить условия, на которые сильный дилер согласится."},{type:"h2",id:"kto-takoj-diler",text:"Дилер, дистрибьютор, агент: кого именно вы ищете"},{type:"p",text:"Слово «дилер» в разговоре означает что угодно — от магазина в райцентре до федерального дистрибьютора. От того, кого вы ищете, зависят и маржа партнёра, и ваши риски."},{type:"table",caption:"Формы партнёрства для выхода в регионы",head:["Партнёр","Чей товар до продажи","Как зарабатывает","Ваши риски","Когда подходит"],rows:[["Дилер","Покупает у вас и продаёт от своего имени","Разница между дилерской и розничной ценой","Дилер может «спать» и занимать территорию","Товар нужно показать, привезти, смонтировать на месте"],["Дистрибьютор","Покупает крупными партиями, держит склад","Скидка за объём, перепродаёт дилерам и магазинам","Высокая зависимость от одного крупного партнёра","Массовый товар, широкая география"],["Агент","Остаётся вашим до продажи","Процент с каждой сделки","Нужен свой склад и логистика","Дорогие проекты, длинный цикл сделки"],["Оптовый покупатель","Покупает партию и дальше не обязан ничего","Своя наценка","Нет контроля цены и сервиса в регионе","Нужно разово загрузить мощности"]],highlight:0,note:"В Гражданском кодексе нет отдельного «дилерского договора»: обычно это смешанный договор с элементами поставки и агентирования (п. 3 ст. 421 ГК РФ). Поэтому условия, о которых ниже, нужно прописать самим."},{type:"p",text:"Для большинства производств — мебели, металлоконструкций, оборудования, стройматериалов — нужен именно дилер: компания, которая покажет продукт клиенту в своём регионе, примет заказ, привезёт и смонтирует. О нём и пойдёт речь дальше."},{type:"h2",id:"ekonomika",text:"Сначала посчитайте: выдержит ли ваша цена дилерскую скидку"},{type:"p",text:"Маржа дилера берётся не из воздуха, а из вашей. Если вы продаёте напрямую с хорошей наценкой, но не готовы отдать партнёру заметную часть, дилерская сеть не взлетит: сильный дилер выберет того, кто платит больше."},{type:"table",caption:"Условный пример: прямая продажа и продажа через дилера",head:["Показатель","Прямая продажа","Через дилера"],rows:[["Цена для конечного клиента","100 000 ₽","100 000 ₽"],["Вы получаете","100 000 ₽","70 000 ₽ (дилерская скидка 30%)"],["Себестоимость изделия","55 000 ₽","55 000 ₽"],["Привлечение клиента и работа продавца","15 000 ₽","—"],["Поддержка дилера: образцы, обучение, материалы","—","2 000 ₽"],["**Ваша маржа с заказа**","**30 000 ₽**","**13 000 ₽**"]],highlight:2,note:"Цифры условные. Реальная скидка зависит от отрасли и от того, что берёт на себя дилер: склад, доставку, монтаж, гарантийный сервис."},{type:"p",text:"С каждого заказа через дилера вы зарабатываете меньше. Канал оправдан, когда приносит **заказы, которых у вас иначе не было бы**: из регионов, куда вы не дотягиваетесь рекламой и продажами, и в объёме, который загружает цех. Если постоянные расходы — аренда, станки, зарплаты — уже покрыты, дополнительные 13 000 ₽ с заказа почти целиком идут в прибыль."},{type:"stats",items:[{v:"13 000 ₽",l:"маржи с заказа через дилера в примере"},{v:"≈70 заказов",l:"в месяц нужно, чтобы заменить 900 000 ₽ маржи ушедшего крупного клиента"},{v:"10 дилеров",l:"по 7 заказов в месяц — вот что стоит за этой цифрой"}]},{type:"p",text:"Пример с крупным клиентом на 900 000 ₽ маржи мы разбирали в статье [«Производство держится на 2–3 клиентах»](/blog/zavisimost-ot-krupnyh-klientov/). Дилерская сеть — один из способов снизить такую зависимость, но не быстрый: это месяцы, а не недели."},{type:"quote",text:"Ваша маржа — моя возможность.",author:"Джефф Безос",role:"основатель Amazon",source:"любимый афоризм Безоса по данным журнала Fortune, 2012",sourceUrl:"https://quoteinvestigator.com/2019/01/13/margin/"},{type:"p",text:"Это правило работает и в обратную сторону. Дилер должен **отрабатывать** свою маржу: показывать продукт, консультировать, привозить, монтировать, решать гарантийные случаи. Если он только перепродаёт, клиенты рано или поздно найдут вас напрямую, а дилер — более выгодного производителя."},{type:"image",image:{src:y("margin"),w:1600,h:900,alt:"Объёмная иллюстрация: стопка монет разделена на три цветных слоя — себестоимость, маржа производителя и маржа дилера",caption:"Скидка дилеру — это часть вашей маржи. Её размер нужно знать до первых переговоров"}},{type:"form",position:1},{type:"h2",id:"portret",text:"Кого искать: портрет дилера для производства"},{type:"p",text:"Лучший дилер — не тот, кто ответил на объявление, а тот, у кого **уже есть ваши клиенты**. Он продаёт им смежный товар и может добавить ваш продукт в ассортимент без перестройки бизнеса."},{type:"list",items:["**Салоны и магазины в нише.** Мебельные салоны, магазины стройматериалов, салоны дверей и окон, магазины оборудования. У них уже есть шоурум и поток покупателей.","**Монтажные и строительные компании.** Они ставят ваш тип продукта на объектах и сами решают, у кого закупать.","**Оптовые базы и дистрибьюторы смежных товаров.** Работают с теми же покупателями, что и вы, и ищут, чем расширить линейку.","**Бывшие дилеры конкурентов.** Знают продукт и рынок, а с прошлым производителем их часто развели цена, сроки или качество.","**Ваши же клиенты из регионов.** Компания, которая регулярно покупает у вас для себя, может начать продавать соседям."]},{type:"p",text:"Прежде чем подписывать договор, проверьте партнёра: выписку из ЕГРЮЛ, отчётность за последние 2–3 года, сколько у него точек продаж и что о нём пишут клиенты. Пятнадцать минут проверки дешевле, чем полгода с дилером, который занял территорию и ничего не продаёт."},{type:"image",image:{src:y("showroom"),w:1600,h:900,alt:"Региональный шоурум дилера: образцы продукции производителя в зале, менеджер консультирует покупателей",caption:"Сильный дилер — тот, у кого уже есть шоурум и покупатели вашего типа продукта"}},{type:"h2",id:"kanaly",text:"6 каналов поиска дилеров и оптовиков"},{type:"p",text:"Ни один канал не даёт дилерскую сеть сам по себе. Лучше всего работает связка: целевой список и прямой выход на собственников плюс реклама, которая приводит тех, кто ищет производителя сам."},{type:"h3",text:"1. Заявки из регионов, которые у вас уже есть"},{type:"p",text:"Откройте CRM или почту за год: сколько заявок пришло из городов, где у вас нет присутствия? Каждая такая заявка — сигнал спроса. Регионы, откуда клиенты пишут сами, — первые кандидаты для поиска дилера. Если заявки нигде не хранятся, начните с этого: без учёта вы не узнаете, какой дилер приносит результат."},{type:"h3",text:"2. Целевая база и прямой выход на собственников"},{type:"p",text:"Соберите список компаний по портрету выше в выбранных регионах: из 2ГИС, Яндекс Карт, отраслевых каталогов и списков участников выставок. Дальше — адресное сообщение собственнику или коммерческому директору с конкретным предложением: что за продукт, какая маржа на типовом заказе, как вы помогаете продавать. Это канал, в котором мы работаем чаще всего: [сообщения в мессенджерах](/services/messenger-outreach/), [письма](/services/email-outreach/) и [голосовые рассылки](/services/voice-mailings/) по базе ЛПР."},{type:"h3",text:"3. Реклама «станьте дилером» в Яндекс Директе"},{type:"p",text:"Компании, которые ищут, чем расширить ассортимент, сами вбивают в поиск «поставщик…», «производитель… опт», «стать дилером…». Под них нужна отдельная кампания по выбранным регионам и [отдельная страница для дилеров](/services/sites/): условия, расчёт маржи на типовом заказе, фото производства, сроки, форма заявки. Обычная главная сайта для розничного клиента дилера не убедит."},{type:"h3",text:"4. Отраслевые выставки"},{type:"p",text:"Выставка — место, где за 3–4 дня можно встретиться с десятками компаний вживую. Но и конкуренция там высокая: на выставке «Металлообработка-2026» было **1 210 экспонентов** и больше **39 000 посетителей-специалистов**. Работает, если идти с планом: заранее выбрать по каталогу участников 20–30 потенциальных партнёров и назначить встречи до выставки, а не ждать, что подойдут к стенду."},{type:"h3",text:"5. B2B-площадки и разделы «ищу дилера»"},{type:"p",text:"Каталоги производителей и площадки с разделами «ищем дилеров» дают входящие обращения почти бесплатно. Минус — там те же объявления сотен производителей, а откликаются чаще те, кто ищет товар подешевле, а не сильные региональные компании. Хороший дополнительный канал, но не основной."},{type:"h3",text:"6. Рекомендации и смежные производители"},{type:"p",text:"Попросите действующих дилеров и клиентов назвать сильные компании в соседних регионах. Договоритесь с производителями смежных товаров, которые не конкурируют с вами: у них уже есть дилерская сеть, и ваш продукт может расширить её ассортимент."},{type:"table",caption:"Сравнение каналов поиска дилеров",head:["Канал","Кого приводит","Первые контакты","Что нужно от вас"],rows:[["Заявки из регионов","Сигнал, где искать","Сразу, если заявки учитываются","CRM или хотя бы таблица заявок"],["База и прямой выход на ЛПР","Компании с вашими клиентами, по портрету","Через 1–2 недели","Портрет дилера, предложение с цифрами"],["Яндекс Директ «станьте дилером»","Тех, кто сам ищет производителя","В первую неделю после запуска","Страница для дилеров, бюджет на регионы"],["Выставки","Активных игроков рынка","За 3–4 дня, но раз в год","Встречи, назначенные заранее"],["B2B-площадки","Много откликов, часто слабых","Сразу","Время на отсев"],["Рекомендации и смежники","Проверенных партнёров","Непредсказуемо","Действующие дилеры и связи"]],highlight:1},{type:"form",position:2},{type:"h2",id:"programma",text:"Дилерская программа: что предложить, чтобы дилер согласился"},{type:"p",text:"Сильному региональному партнёру производители предлагают сотрудничество каждую неделю. Он выбирает не по красоте каталога, а по тому, сколько заработает и сколько сил потратит. Поэтому программа должна отвечать на его вопросы раньше, чем он их задаст."},{type:"table",caption:"Условия дилерской программы: как обычно и как сильнее",head:["Условие","Как обычно предлагают","Как предложить сильнее"],rows:[["Скидка","«Скидка 25% от прайса»","Маржа дилера в рублях на типовом заказе плюс бонус за объём по итогам квартала"],["Старт","Большая обязательная закупка","Пробная партия или выставочный образец со скидкой, дальше — под заказ"],["Территория","Эксклюзив на область навсегда","Приоритет на территории при выполнении плана, пересмотр раз в полгода"],["Клиенты","Дилер ищет покупателей сам","Передаём дилеру заявки из его региона с сайта и рекламы"],["Маркетинг","«Пришлём каталог»","Фото и видео производства, страница дилера на вашем сайте, материалы для Avito и Яндекс Карт"],["Обучение и сервис","Не обсуждается","Обучение менеджеров, техподдержка, понятный срок по гарантийным случаям"],["Оплата","100% предоплата всегда","Отсрочка после 2–3 успешных заказов"],["Цена для клиента","«Продавать не ниже РРЦ», штраф за нарушение","Рекомендованная цена без санкций или максимальная цена перепродажи"]],highlight:2},{type:"key",title:"Главный аргумент",text:"Дилеру нужны не скидки, а покупатели. Производитель, который **передаёт заявки из региона** и даёт материалы для рекламы, выигрывает у того, кто просто даёт скидку на 5% больше."},{type:"p",text:"Здесь маркетинг производителя работает на всю сеть: одна рекламная кампания по регионам, одна страница с адресами дилеров — и каждый партнёр получает обращения, которые сам бы не привлёк. Заявки при этом остаются в вашей CRM, и вы видите, кто из дилеров их отрабатывает."},{type:"image",image:{src:y("meeting"),w:1600,h:900,alt:"Переговоры собственника производства с региональным дилером: на столе образцы продукции и распечатанный расчёт маржи",caption:"Предложение дилеру убеждает цифрами: сколько он заработает на типовом заказе и где возьмёт покупателей"}},{type:"h2",id:"zakon",text:"Два условия, которые нельзя писать в дилерском договоре"},{type:"p",text:"Желание защитить цену и не делиться дилером с конкурентами понятно. Но закон о защите конкуренции (ч. 2 ст. 11 Федерального закона № 135-ФЗ) прямо запрещает в «вертикальных» соглашениях производителя и дилера два популярных условия."},{type:"steps",items:["**Обязательная цена перепродажи.** Нельзя обязать дилера продавать по вашей цене или не ниже её. Можно установить только **максимальную** цену перепродажи. Рекомендованная цена допустима, пока за отклонение от неё нет штрафов, угроз прекратить поставки и других санкций.","**Запрет продавать товары конкурентов.** Нельзя требовать, чтобы дилер не продавал продукцию других производителей. Исключение — если дилер продаёт ваш товар под вашим товарным знаком или другим средством индивидуализации."]},{type:"p",text:"За такие соглашения по ст. 14.32 КоАП РФ компании грозит штраф от 1 до 15% выручки от продажи товара на соответствующем рынке. Это не повод отказываться от дилеров — это повод показать договор юристу до подписания."},{type:"note",text:"Мы не юристы, и этот раздел — не юридическая консультация. Он нужен, чтобы вы знали, какие вопросы задать юристу, когда будете готовить дилерский договор."},{type:"h2",id:"plan",text:"План запуска на 90 дней"},{type:"steps",items:["**Недели 1–2. Экономика и программа.** Маржа по продуктам, допустимая скидка, условия программы, проект договора — сразу к юристу. Выберите 3–5 регионов по заявкам и спросу.","**Недели 3–4. База и упаковка.** Список 100–300 компаний по портрету в выбранных регионах. Страница для дилеров на сайте, презентация с расчётом маржи, фото и видео производства.","**Месяц 2. Контакты.** Адресные сообщения и звонки собственникам, реклама «станьте дилером» по регионам, встречи с теми, кто ответил. Все контакты — в CRM.","**Месяц 3. Пробные партии.** 2–3 дилера с пробной партией или образцами. Через 1–2 месяца — первые отчёты о продажах, решение о расширении."]},{type:"p",text:"Начинайте с 2–3 дилеров, а не с десяти. Так вы успеете обучить каждого, отладить логистику и понять, какие условия работают, прежде чем тиражировать программу на другие регионы."},{type:"image",image:{src:y("network"),w:1600,h:900,alt:"Объёмная иллюстрация: миниатюрный завод в центре платформы соединён зелёными дорогами с региональными магазинами, несколько магазинов ещё не подключены",caption:"Сеть растёт по одному дилеру: сначала 2–3 партнёра, потом тиражирование на новые регионы"}},{type:"h2",id:"oshibki",text:"Ошибки, из-за которых дилерская сеть не работает"},{type:"list",items:["**Искать «кого угодно».** Объявление без портрета приводит людей без магазина, клиентов и денег на закупку.","**Не посчитать маржу заранее.** Скидку называют на переговорах «на глаз», а через полгода выясняется, что дилерские заказы не покрывают даже производство.","**Раздать эксклюзивы.** Территория закреплена за дилером, который продаёт два заказа в год, и туда уже не зайти.","**Подписать и забыть.** Без обучения, материалов и заявок из региона даже сильный дилер через пару месяцев переключится на другого производителя.","**Конкурировать с дилером ценой.** Если на вашем сайте тот же товар дешевле, чем у дилера, вы сами отбираете у него клиентов.","**Не вести учёт.** Без CRM непонятно, какой дилер растёт, а какой только занимает территорию."]},{type:"h2",id:"metriki",text:"Как понять, что дилерский канал работает"},{type:"p",text:"Подписанный договор — ещё не результат. Собственнику достаточно раз в месяц смотреть на пять цифр:"},{type:"list",items:["**Активные дилеры** — сколько партнёров сделали хотя бы один заказ за последние 90 дней.","**Повторные заказы** — сколько дилеров заказали второй и третий раз. Это главный сигнал, что продукт продаётся.","**Выручка на одного активного дилера** и её динамика по кварталам.","**Доля дилерского канала в выручке** — и как меняется доля крупнейших клиентов.","**Скорость отработки заявок**, которые вы передали дилерам: кто звонит клиенту в тот же день, а кто через неделю."]},{type:"p",text:"Свести эти цифры в один экран помогает [сквозная аналитика](/services/analytics/). На заводе металлоизделий, который 20 лет продавал через дилеров и связи владельца, мы начали именно с прозрачности: заявки в Битрикс24, записи звонков, ответ клиенту в среднем **за 25 минут**. Теперь собственник видит заявки, расходы и закрытые сделки в онлайне. [Разбор кейса](/cases/metal-factory-two-landings/)."},{type:"products",title:"Чем можем помочь",items:[{href:"/services/messenger-outreach/",title:"Прямой выход на дилеров",text:"Собираем базу компаний по портрету в регионах и пишем собственникам"},{href:"/services/yandex-direct/",title:"Реклама «станьте дилером»",text:"Кампании по выбранным регионам и заявки для действующих дилеров"},{href:"/services/sites/",title:"Страница для дилеров",text:"Условия, расчёт маржи, производство и форма заявки на одном экране"}]},{type:"h2",id:"zaklyuchenie",text:"Заключение"},{type:"list",items:["Решите, кого ищете: дилера, дистрибьютора, агента или оптовика. От этого зависят маржа партнёра и ваши риски.","Посчитайте, какую скидку выдержит ваша маржа, до первого звонка дилеру.","Ищите тех, у кого уже есть ваши клиенты: салоны, монтажников, оптовиков смежных товаров.","Связка каналов: целевая база и прямой выход на собственников, реклама «станьте дилером», выставки по плану.","Дилеру нужны покупатели: передавайте заявки из региона и давайте материалы для рекламы.","Не пишите в договоре обязательную цену перепродажи и запрет на товары конкурентов — покажите договор юристу.","Начинайте с 2–3 дилеров и судите по повторным заказам, а не по числу подписанных договоров."]},{type:"p",text:"Если хотите, разберём ваш случай: посчитаем допустимую дилерскую скидку, выберем регионы и каналы поиска под ваш продукт. 30 минут на созвоне, без обязательств."},{type:"form",position:3}],faq:[{q:"Как найти дилеров для своей продукции?",a:"Выберите 3–5 регионов, откуда уже приходят заявки или где работают компании, похожие на ваших клиентов. Соберите базу салонов, монтажных компаний и оптовиков в этих регионах и напишите напрямую собственникам с расчётом маржи на типовом заказе. Параллельно запустите рекламу «станьте дилером» в Яндекс Директе по этим регионам и назначайте встречи на отраслевых выставках."},{q:"Какую скидку давать дилеру?",a:"Такую, которую выдержит ваша маржа и которая окупает работу дилера: показ продукта, доставку, монтаж и сервис. Посчитайте маржу с заказа при прямой продаже и через дилера — в примере в статье это 30 000 ₽ и 13 000 ₽. Дилерский канал оправдан, если приносит заказы, которых у вас иначе не было бы."},{q:"Можно ли обязать дилера продавать по рекомендованной цене?",a:"Нет. По ч. 2 ст. 11 закона № 135-ФЗ «О защите конкуренции» производитель может установить дилеру только максимальную цену перепродажи. Рекомендованная цена допустима, пока за отклонение от неё нет штрафов и угроз прекратить поставки. Договор лучше показать юристу."},{q:"Можно ли запретить дилеру продавать товары конкурентов?",a:"По общему правилу нет: закон о защите конкуренции запрещает такое условие в соглашениях производителя и дилера. Исключение — если дилер продаёт ваш товар под вашим товарным знаком. Детали стоит обсудить с юристом до подписания договора."},{q:"Сколько времени нужно, чтобы запустить дилерскую сеть?",a:"Первые 2–3 дилера с пробными партиями — примерно за 90 дней: 2 недели на экономику и программу, 2 недели на базу и упаковку, месяц на контакты и встречи, месяц на пробные партии. Ещё 1–2 месяца нужно, чтобы по отчётам о продажах понять, кого из дилеров развивать."},{q:"Что важнее для дилера: скидка или заявки?",a:"Для сильного дилера — заявки. Производитель, который передаёт обращения из региона и даёт фото, видео и материалы для рекламы, выигрывает у того, кто просто даёт скидку на несколько процентов больше."}],sources:[{title:"Статья 11. Запрет на ограничивающие конкуренцию соглашения хозяйствующих субъектов (Федеральный закон № 135-ФЗ «О защите конкуренции»)",publisher:"КонсультантПлюс",url:"https://www.consultant.ru/document/cons_doc_LAW_61763/75fad2ba0bd186dad16ff04a2efe55ae3f9ff7e6/"},{title:"Цена перепродажи в дилерском договоре: что запрещено и что допустимо",publisher:"Юридическая фирма VITVET",url:"https://vitvet.com/articles/dilerskij_dogovor/cena_pereprodazhi/"},{title:"Итоги выставки «Металлообработка-2026»",publisher:"Экспоцентр, официальный сайт выставки",url:"https://www.metobr-expo.ru/ru/media/news/index.php?id4=20927"},{title:"Как и зачем компаниям развивать дилерскую сеть",publisher:"Журнал Битрикс24",url:"https://www.bitrix24.ru/journal/dilerskaya-set-kak-postroit-i-razvivat/"},{title:"Quote Origin: Your Margin Is My Opportunity",publisher:"Quote Investigator (со ссылкой на Fortune, 2012)",url:"https://quoteinvestigator.com/2019/01/13/margin/"},{title:"Кейс: завод металлоизделий — два лендинга, CRM и рост конверсии в 2,5 раза",publisher:"Квалити",url:"https://kvaliti-team.ru/cases/metal-factory-two-landings/"}],comments:[{name:"Тимур Кисиев",role:"основатель «Квалити», автор статьи",date:"2026-10-25",team:!0,text:"Частая картина: у производства 15 «дилеров» по договору, а заказывают двое. Прежде чем искать новых, посмотрите, сколько партнёров сделали заказ за последние 90 дней. Иногда выгоднее сначала дать заявки и материалы тем, кто уже есть."}]},c="kak-proverit-marketingovogo-podryadchika",u=t=>`/blog/${c}/${t}.webp`,m=[{slug:c,href:`/blog/${c}/`,hub:"upravlenie-marketingom",kind:"article",label:"Гайд",published:"2026-10-31",tags:["аудит маркетинга","подрядчик","контроль","отчётность"],title:"Как проверить маркетингового подрядчика за час, даже если вы не маркетолог: 3 доступа, 5 цифр и 10 вопросов",seoTitle:"Аудит маркетинга за час: как собственнику проверить подрядчика",description:"Пошаговая проверка маркетингового подрядчика для собственника без опыта в рекламе: какие доступы должны быть у вас, 5 цифр до договора, 10 вопросов подрядчику и признаки, что бюджет сливается.",sub:"Подрядчик присылает отчёт: клики растут, заявки дешевеют, а продаж больше не становится. Разбираем, как за час понять, работает ли ваш маркетинг, не заходя в настройки рекламы.",meta:"13 минут чтения · управление маркетингом",cover:u("hero"),hero:{src:u("hero"),w:1600,h:900,alt:"Собственник производства за столом в кабинете внимательно изучает отчёт подрядчика по рекламе на ноутбуке, рядом распечатка с цифрами",caption:"Чтобы проверить подрядчика, не нужно разбираться в настройках рекламы. Достаточно знать, какие цифры спросить"},shortAnswer:"Проверить маркетингового подрядчика можно за час без специальных знаний. Сначала убедитесь, что у вас есть собственные доступы к рекламным кабинетам, аналитике и CRM, а реклама промаркирована. Затем возьмите пять цифр за последние три месяца: расход, заявки, долю целевых заявок, число договоров из рекламы и цену одного договора. Сравните цену договора с тем, сколько вы можете платить за клиента при вашей марже. Если подрядчик не может назвать число договоров из рекламы, проблема не в настройках, а в учёте: без связи рекламы с CRM никто не знает, окупается ли бюджет.",cases:["kitchens-rostov","metal-factory-two-landings","industrial-robots"],body:[{type:"p",text:"Типичная ситуация: маркетингом занимается подрядчик — агентство, фрилансер или штатный специалист. Раз в месяц приходит отчёт: показы, клики, CTR, цена заявки. Цифры растут, графики зелёные. А вы смотрите на выручку и не понимаете, есть ли от всего этого толк."},{type:"p",text:"Погружаться в настройки рекламы собственнику не нужно — для этого и нанят подрядчик. Но проверить, что деньги работают, можно и нужно самому. Ниже — проверка в четыре шага, которая занимает около часа и не требует знаний в рекламе."},{type:"h2",id:"otchet",text:"Почему отчёт подрядчика не отвечает на главный вопрос"},{type:"p",text:"Подрядчик обычно отчитывается тем, что видит в рекламном кабинете. Собственнику нужны другие цифры — те, что видны в кассе и CRM. Между ними разрыв, и именно в нём теряются деньги."},{type:"table",caption:"Что показывает отчёт подрядчика и что нужно собственнику",head:["Метрика из отчёта","Что она говорит","Чего она не говорит"],rows:[["Показы, клики, CTR","Объявления видят и на них нажимают","Ничего о деньгах: клик не равен покупателю"],["Цена заявки","Сколько стоит одно обращение","Сколько из этих обращений — ваши клиенты, а сколько — спам и «просто спросить»"],["Число заявок","Сколько людей оставили контакты","Сколько из них дошли до договора"],["ROMI по заявкам","Окупаемость по расчётной стоимости заявки","Реальную окупаемость: часть «окупаемых» заявок не покупает"],["**Договоры и выручка из рекламы**","**Сколько денег принесла реклама**","—"]],highlight:2},{type:"p",text:"Как заявки с хорошим ROMI оказываются убыточными, мы подробно разбирали в статье [«Почему лиды с ROMI 400% могут быть убыточными»](/blog/hidden-losses-behind-romi/)."},{type:"quote",text:"Половина денег, которые я трачу на рекламу, уходит впустую. Беда в том, что я не знаю, какая именно половина.",author:"Джон Ванамейкер",role:"основатель сети универмагов в США (авторство фразы приписывается)",source:"Quote Investigator, 2022",sourceUrl:"https://quoteinvestigator.com/2022/04/11/advertising/"},{type:"p",text:"Сто лет назад это было неизбежно. Сегодня ответ находится за час — если реклама связана с CRM и подрядчик готов показать путь от расхода до договора."},{type:"h2",id:"dostupy",text:"Шаг 1. Доступы и маркировка — 15 минут"},{type:"p",text:"Первое, что стоит проверить, — не качество рекламы, а то, кому она принадлежит. Если завтра вы расстанетесь с подрядчиком, у вас должны остаться история кампаний, статистика и данные о клиентах."},{type:"table",caption:"Чек-лист доступов собственника",head:["Что проверить","Как должно быть","Тревожный знак"],rows:[["Рекламные кабинеты: Яндекс Директ, VK Реклама, Avito","У вас есть свой вход: полный доступ или хотя бы просмотр статистики","«Доступ не нужен, мы всё пришлём в отчёте»"],["Яндекс Метрика или другая аналитика","Счётчик заведён на ваш аккаунт, у подрядчика — доступ","Счётчик на аккаунте подрядчика или фрилансера"],["CRM и телефония","Заявки с сайта и звонки попадают в CRM, звонки записываются","Заявки приходят на почту менеджеру, звонки не записываются"],["Маркировка рекламы","В объявлениях есть пометка «Реклама» и идентификатор erid, данные передаются в ЕРИР","Никто не знает, кто и как передаёт данные"],["Договор","Прописано, как передаются кабинеты и данные при расторжении","Об этом в договоре ничего нет"]],highlight:1},{type:"p",text:"Про Яндекс Директ важно знать одну деталь. Если реклама ведётся из агентского кабинета, в справке Директа владельцем организации указан главный представитель агентства. Клиент при этом может получить полный доступ или доступ «только чтение» к своим кампаниям и статистике. Попросите такой доступ и уточните в договоре, что будет с кампаниями и их историей, если вы смените подрядчика."},{type:"p",text:"Маркировка — не формальность. По данным eLama на ноябрь 2025 года, штраф для юрлица по ст. 14.3 КоАП РФ за рекламу без идентификатора erid или без отчётности в ЕРИР — от 200 000 до 500 000 ₽, и штрафы за разные публикации складываются. Кто отвечает за маркировку и отчётность — подрядчик, сервис или вы сами, — должно быть записано в договоре."},{type:"image",image:{src:u("keys"),w:1600,h:900,alt:"Объёмная иллюстрация: три ключа на светлой подставке — к рекламному кабинету, аналитике и CRM, рядом миниатюрный офис производства",caption:"Три доступа, которые должны быть у собственника: рекламные кабинеты, аналитика и CRM"}},{type:"h2",id:"cifry",text:"Шаг 2. Пять цифр до договора — 20 минут"},{type:"p",text:"Попросите подрядчика или посмотрите сами пять цифр за последние три месяца. Месяца мало: у производств длинный цикл сделки, и часть договоров приходит с задержкой."},{type:"steps",items:["**Расход на рекламу** — сколько всего ушло в рекламные системы, плюс оплата работы подрядчика.","**Заявки** — сколько обращений пришло: формы, звонки, сообщения в мессенджерах.","**Доля целевых заявок** — сколько из них действительно ваши клиенты. Это видно в CRM по отметкам менеджеров.","**Договоры из рекламы** — сколько сделок закрыто с клиентами, которые пришли с рекламы.","**Цена договора** — расход, делённый на число договоров. Её сравнивают с допустимой ценой клиента при вашей марже."]},{type:"table",caption:"Условный пример: проверка за три месяца",head:["Показатель","Значение","Как считается"],rows:[["Расход на рекламу","300 000 ₽","Из рекламных кабинетов"],["Заявки","150","Цена заявки 2 000 ₽"],["Целевые заявки","60 (40%)","Отметки менеджеров в CRM"],["Договоры из рекламы","9","Сделки с источником «реклама» в CRM"],["Цена договора","≈33 300 ₽","300 000 ₽ ÷ 9"],["Маржа с договоров","1 080 000 ₽","9 × средний чек 400 000 ₽ × маржа 30%"],["**Итог после рекламы и работы подрядчика**","**+660 000 ₽**","1 080 000 − 300 000 − 120 000 (подрядчик, 3 месяца по 40 000 ₽)"]],highlight:1,note:"Цифры условные. Допустимую цену клиента считаем от маржи — подробно в статье «Сколько производству тратить на маркетинг»."},{type:"p",text:"Если цена договора меньше маржи с договора — реклама окупается, даже если заявки кажутся дорогими. Как посчитать допустимую цену клиента для вашего производства, мы разбирали в статье [«Сколько производству тратить на маркетинг»](/blog/skolko-tratit-na-marketing-proizvodstvu/)."},{type:"key",title:"Главное",text:"Если подрядчик не может назвать число договоров из рекламы, проблема не в настройках, а в учёте. Без связи рекламы с CRM **никто не знает**, окупается ли ваш бюджет, — ни вы, ни подрядчик."},{type:"form",position:1},{type:"h2",id:"voprosy",text:"Шаг 3. 10 вопросов подрядчику — 15 минут"},{type:"p",text:"Задайте эти вопросы на созвоне или письмом. Важны не формулировки, а то, может ли подрядчик ответить конкретными цифрами и показать их на экране."},{type:"table",caption:"10 вопросов маркетинговому подрядчику",head:["Вопрос","Хороший ответ","Тревожный ответ"],rows:[["Сколько договоров принесла реклама за 3 месяца?","Число и список сделок из CRM","«Мы отвечаем за заявки, продажи — это ваш отдел»"],["Какая доля заявок целевая?","Процент по отметкам менеджеров, причины нецелевых","«Все заявки целевые»"],["Сколько стоит один договор и сколько мы можем за него платить?","Цена договора и расчёт от вашей маржи","Говорит только о цене клика и заявки"],["Какие кампании дают договоры, а какие — только заявки?","Разбивка по кампаниям и каналам","«Все кампании работают в связке»"],["Что отключили за последний месяц и почему?","Конкретные кампании и цифры, по которым решили","«Ничего, всё работает»"],["Передаются ли статусы сделок из CRM в рекламу?","Да, реклама обучается на договорах или квалифицированных заявках","«Это сложно, не нужно»"],["Есть ли у меня доступ к кабинетам и аналитике?","Да, сейчас пришлём","Отказ или «зачем вам»"],["Кто отвечает за маркировку рекламы?","Называет, кто передаёт данные в ЕРИР","Не знает"],["Что будет с кампаниями, если мы расстанемся?","Передадим кабинеты и историю","«Кампании — наша разработка»"],["Какой план на следующий месяц и какой результат вы ожидаете?","Гипотезы и ожидаемые цифры по заявкам и договорам","«Продолжаем оптимизацию»"]],highlight:1},{type:"image",image:{src:u("meeting"),w:1600,h:900,alt:"Собственник производства задаёт вопросы маркетинговому подрядчику на встрече в переговорной, подрядчик показывает цифры на ноутбуке",caption:"Хороший подрядчик отвечает цифрами и сразу показывает их на экране"}},{type:"h2",id:"zvonki",text:"Шаг 4. Послушайте 5 звонков — 10 минут"},{type:"p",text:"Иногда реклама работает, а заявки теряются в отделе продаж: менеджер перезванивает через день, не уточняет задачу, не высылает расчёт. Тогда менять подрядчика бесполезно — новый столкнётся с той же проблемой."},{type:"p",text:"Откройте записи пяти последних звонков по рекламным заявкам и обратите внимание на три вещи: как быстро ответили, выяснил ли менеджер задачу и бюджет и договорился ли о следующем шаге. На заводе металлоизделий одна эта проверка показала, что заявки ждали ответа часами и даже днями. После настройки CRM и телефонии ответ стал приходить **в среднем за 25 минут**. [Разбор кейса](/cases/metal-factory-two-landings/)."},{type:"image",image:{src:u("calls"),w:1600,h:900,alt:"Собственник производства в наушниках слушает записи звонков отдела продаж за рабочим столом, рядом блокнот с пометками",caption:"Пять записей звонков за 10 минут показывают, где теряются заявки: в рекламе или в продажах"}},{type:"p",text:"Больше о том, как заявки теряются между рекламой и договором, — в разделе [«Отдел продаж»](/blog/otdel-prodazh/)."},{type:"h2",id:"priznaki",text:"Признаки, что бюджет сливается"},{type:"list",items:["**В отчёте нет ни одного договора** — только клики, показы и цена заявки.","**Цена заявки падает, а продаж не больше.** Часто это значит, что реклама собирает дешёвый нецелевой трафик.","**У вас нет доступа к кабинетам** или его дают «по запросу» и с задержкой.","**Отчёты одинаковые из месяца в месяц**: «провели оптимизацию», без конкретных изменений и цифр.","**Менеджеры жалуются на качество заявок**, а подрядчик отвечает, что это проблема продаж, не проверив звонки.","**Бюджет растёт, а план не меняется**: «нужно больше бюджета, чтобы алгоритмы обучились».","**Никто не знает, кто отвечает за маркировку** и передачу данных в ЕРИР."]},{type:"h2",id:"itogi",text:"Что делать по итогам проверки"},{type:"table",caption:"Результаты проверки и следующий шаг",head:["Что получилось","Что это значит","Что делать"],rows:[["Доступы есть, договоры считаются, цена договора ниже маржи","Маркетинг работает","Оставить подрядчика, обсудить рост бюджета или новых каналов"],["Доступы есть, но договоры не считаются","Нет связи рекламы с CRM","Настроить учёт: источник сделки в CRM, передача статусов в рекламу"],["Договоры считаются, но цена договора выше маржи","Реклама убыточна","Пересобрать кампании под целевые заявки, проверить посадочные и продажи"],["Заявки целевые, договоров мало","Потери в отделе продаж","Скорость ответа, скрипт, контроль звонков — до изменения рекламы"],["Доступов нет, на вопросы нет ответов","Вы не контролируете маркетинг","Забрать доступы и данные, искать подрядчика с прозрачной отчётностью"]],highlight:2},{type:"form",position:2},{type:"h2",id:"kak-my",text:"Как мы отчитываемся перед собственником"},{type:"p",text:"Мы сами работаем по тем правилам, которые описали выше. С первого дня настраиваем цели, коллтрекинг и связь с CRM, а статусы сделок передаём обратно в рекламный кабинет. Раз в две недели — отчёт на одном экране и созвон: расход, заявки, квалифицированные заявки, договоры, выручка и окупаемость. Доступы к кабинетам и аналитике всегда у клиента."},{type:"p",text:"Пример: производство кухонь в Ростове-на-Дону получило **890 заявок по 1 220 ₽ и 99 договоров** за полтора года — эти цифры видны не в рекламном кабинете, а в CRM клиента. [Разбор кейса](/cases/kitchens-rostov/)."},{type:"image",image:{src:u("funnel"),w:1600,h:900,alt:"Объёмная иллюстрация: прозрачная воронка, в которую сверху падает много монет, а снизу выходят несколько зелёных папок с договорами",caption:"Главная цифра в отчёте — не заявки, а договоры, которые получились из рекламного бюджета"}},{type:"products",title:"Чем можем помочь",items:[{href:"/services/analytics/",title:"Аналитика и аудит",text:"Связываем рекламу с CRM и показываем путь от расхода до договора"},{href:"/services/yandex-direct/",title:"Яндекс Директ под договоры",text:"Кампании, которые обучаются на сделках, а не на кликах"},{href:"/services/sites/",title:"Посадочные страницы",text:"Отдельные страницы под направления, чтобы целевых заявок было больше"}]},{type:"h2",id:"zaklyuchenie",text:"Заключение"},{type:"list",items:["Доступы к рекламным кабинетам, аналитике и CRM должны быть у вас, а не только у подрядчика.","Кто отвечает за маркировку рекламы и что будет с кабинетами при расторжении — записано в договоре.","Пять цифр за три месяца: расход, заявки, доля целевых, договоры из рекламы, цена договора.","Цену договора сравнивайте с маржой, а не с ценой заявки у конкурентов.","Хороший подрядчик отвечает на вопросы цифрами и показывает их на экране.","Прежде чем менять подрядчика, послушайте звонки: заявки могут теряться в продажах."]},{type:"p",text:"Если хотите, проведём эту проверку вместе: посмотрим ваши кабинеты, CRM и пять цифр и скажем, где теряются деньги. 30 минут на созвоне, без обязательств."},{type:"form",position:3}],faq:[{q:"Как проверить работу маркетингового подрядчика, если я не разбираюсь в рекламе?",a:"Не заходите в настройки — проверьте результат. Получите свои доступы к рекламным кабинетам, аналитике и CRM. Затем возьмите пять цифр за три месяца: расход, заявки, долю целевых заявок, договоры из рекламы и цену договора. Если цена договора ниже маржи с договора, реклама окупается."},{q:"Что такое аудит маркетинга и чем он отличается от аудита рекламы?",a:"Аудит рекламы проверяет настройки кампаний: ключевые слова, объявления, ставки. Аудит маркетинга смотрит шире: окупается ли бюджет в договорах, связаны ли реклама и CRM, не теряются ли заявки в отделе продаж. Собственнику важнее второй."},{q:"Должен ли подрядчик давать доступ к рекламному кабинету?",a:"Да. В Яндекс Директе клиент агентства может получить полный доступ или доступ «только чтение» к своим кампаниям и статистике. Отказ дать доступ — тревожный знак. Также стоит прописать в договоре, как передаются кабинеты и история кампаний при расторжении."},{q:"Кто отвечает за маркировку рекламы — агентство или рекламодатель?",a:"Обязанности есть у всех участников цепочки, поэтому распределение нужно закрепить в договоре: кто получает идентификатор erid и передаёт данные в ЕРИР. По данным eLama на ноябрь 2025 года, штраф для юрлица за рекламу без erid или без отчётности в ЕРИР — от 200 000 до 500 000 ₽."},{q:"Как понять, что подрядчик сливает бюджет?",a:"Основные признаки: в отчётах нет договоров, цена заявки падает, а продаж не больше, у вас нет доступа к кабинетам, отчёты не меняются от месяца к месяцу, а на жалобы о качестве заявок подрядчик отвечает, что это проблема продаж, не проверив звонки."},{q:"Сколько стоит аудит маркетинга в Квалити?",a:"Первичный разбор — бесплатный созвон на 30 минут: смотрим кабинеты, CRM и ключевые цифры и говорим, где теряются деньги. Ведение маркетинга командой в фиксированном формате — от 40 000 ₽ в месяц плюс рекламный бюджет."}],sources:[{title:"Работа с клиентами: доступы клиента агентства к кампаниям и статистике",publisher:"Справка Яндекс Директа",url:"https://yandex.com/support/direct/ru/agencies/manage-clients"},{title:"Штрафы и ответственность за несоблюдение закона о маркировке рекламы",publisher:"eLama",url:"https://elama.ru/blog/oshtrafah-iotvetstvennosti-zanesoblyudenie-zakona-omarkirovke-reklamy/"},{title:"Quote Origin: One-Half the Money I Spend for Advertising Is Wasted",publisher:"Quote Investigator, 2022",url:"https://quoteinvestigator.com/2022/04/11/advertising/"},{title:"Почему лиды с ROMI 400% могут быть убыточными",publisher:"Квалити",url:"https://kvaliti-team.ru/blog/hidden-losses-behind-romi/"},{title:"Кейс: завод металлоизделий — два лендинга, CRM и рост конверсии в 2,5 раза",publisher:"Квалити",url:"https://kvaliti-team.ru/cases/metal-factory-two-landings/"},{title:"Кейс: производство кухонь, Ростов-на-Дону",publisher:"Квалити",url:"https://kvaliti-team.ru/cases/kitchens-rostov/"}],comments:[{name:"Тимур Кисиев",role:"основатель «Квалити», автор статьи",date:"2026-10-31",team:!0,text:"Когда к нам приходят на аудит, первым делом просим показать, сколько договоров принесла реклама за квартал. Часто этой цифры нет ни у собственника, ни у подрядчика. С этого и начинаем: пока договоры не считаются, спорить о настройках рекламы бессмысленно."}]},h,l,r,s,{slug:"orion-yandex-direct",hub:"rost-prodazh",published:"2026-09-24",updated:"2026-10-07",kind:"article",label:"Кейс",tags:["директ","мебельное производство"],title:"Кейс фабрики Орион: 12 договоров и 1,5+ млн из Яндекс Директ",sub:"Как мебельное производство из Уфы, которое жило только на рекомендациях, за 4 месяца получило 12 договоров и 1,5+ млн ₽ из рекламы.",meta:"15 минут чтения · мебельное производство",figure:"1,5+ млн ₽",figureBg:"/blog/orion/card-bg.webp",href:"/blog/orion-yandex-direct/",customPage:!0},{slug:"hidden-losses-behind-romi",hub:"ekonomika-klienta",published:"2026-09-24",kind:"article",label:"Аналитика",tags:["аналитика"],title:"Почему лиды с ROMI 400% могут быть убыточными",sub:"Собственнику показывают красивый отчёт маркетолога — а с каждой «окупаемой» сделки бизнес теряет деньги.",meta:"10 минут чтения · экономика",figure:"−7 000 ₽",figureLabel:"убыток с «окупаемой» сделки при ROMI 400%",href:"/blog/hidden-losses-behind-romi/",body:[{type:"p",text:"Ваш маркетолог показывает красочный отчёт: «ROMI 400%! CPL ниже рынка! KPI перевыполнен». Вы платите ему премию, а после недоумеваете, куда уходят деньги с расчётного счёта."},{type:"p",text:"Дело в том, что классические метрики вроде ROMI и CPL — это верхушка айсберга. Под водой скрывается ваша полная себестоимость и операционные расходы (OPEX): производство, монтаж, выезд замерщика, гарантия, рассрочки и комиссии банка. Маркетолог считает свою часть воронки — от клика до заявки и, в лучшем случае, до сделки. А что происходит с деньгами дальше, чаще всего не считает никто."},{type:"h3",text:"Почему «окупаемый лид» может быть финансовой ямой"},{type:"p",text:"Представьте ситуацию: к вам приходит клиент и покупает шкаф-купе за 300 000 ₽."},{type:"list",items:["✅ ROMI 400% — выглядит блестяще.","✅ CPL 5 000 ₽ — кажется, очень дёшево."]},{type:"p",text:"Однако, как в старом анекдоте: «Есть нюанс» 🧐"},{type:"list",items:["Себестоимость материалов и производства: **220 000 ₽**","Доля OPEX (аренда, ФОТ администрации, налоги) на один проект: **35 000 ₽**","Реальные затраты на привлечение (CPO + ФОТ маркетинга + выезд замерщика): **52 000 ₽**"]},{type:"p",text:"Итог: 300 000 − 220 000 − 35 000 − 52 000 = **7 000 ₽ убытка** с каждой такой «окупаемой» сделки."},{type:"p",text:"Мы называем это **MAP (Margin After Promotion)** — маржа после всех затрат. Единственный показатель, который имеет значение в замерном бизнесе, и в частности в мебельном сегменте."},{type:"h3",text:"Что обычно прячется за красивым ROMI"},{type:"p",text:"По отдельности каждая из следующих статей расходов кажется мелочью, о которой можно забыть до конца квартала. Вместе они превращают отчётный ROMI 400% в реальный убыток — просто он не виден, пока вы не посчитали полную экономику конкретного заказа, а не усреднённую по всей рекламной кампании."},{type:"list",items:["Скидки, которые менеджеры дают на этапе переговоров, не попадают в отчёт маркетолога — а в вашу маржу попадают.","Доп. выезды, обмеры и переделки по гарантии считаются «издержками производства», хотя фактически съедают маржу именно того лида, который казался дешёвым.","Рассрочка, эквайринг и комиссии платёжных сервисов тихо забирают ещё 2–5% с каждой сделки.","Логистика и монтаж на удалённые объекты часто не заложены в среднюю себестоимость, которой оперирует отчёт."]},{type:"h3",text:"Что мы делаем на стратегической сессии"},{type:"p",text:"На стратегической сессии мы за 30 минут:"},{type:"list",items:["1️⃣ Разберём структуру затрат вашего типичного заказа — от себестоимости до OPEX и реальной стоимости привлечения.","2️⃣ Покажем, по какой формуле мы вычисляем реальную, а не рекламную маржу (MAP), и сколько денег на самом деле приносит ваш маркетинг.","3️⃣ Сформируем 2–3 гипотезы, какие клиенты и каналы привлечения скрыто съедают вашу прибыль — и что с этим делать в первую очередь."]},{type:"note",text:"P.S. Красивые цифры в отчётах не оплачивают ваши счета. Это делают только реальные деньги, оседающие на счету. Если ваш маркетинг не считает полную экономику проекта, он **гарантированно** играет в рулетку на ваши деньги."},{type:"p",text:"Готовы узнать, во сколько вам, на самом деле, обходятся ваши лиды?"}]},{slug:"construction-site-review",hub:"upravlenie-marketingom",kind:"video",label:"Видеоразбор",tags:["сайты"],title:"Разбор сайта строительной компании",sub:"Что мешает оставить заявку и как это чинится за неделю.",meta:"12 минут · сайты",cover:"/blog/covers/construction-site-review.webp",comingSoon:!0},{slug:"production-priority-system",hub:"otdel-prodazh",published:"2026-09-24",kind:"article",label:"Аналитика",tags:["аналитика"],title:"Как система приоритетов производства увеличила чистую прибыль на 400 000 ₽ в месяц",sub:"Фабрика была загружена на 90%, а прибыль не росла — потому что цех работал по принципу «кто громче кричит», а не по экономике заказа.",meta:"8 минут чтения · производство",figure:"+400 000 ₽",figureLabel:"чистой прибыли в месяц после внедрения приоритетов",href:"/blog/production-priority-system/",body:[{type:"p",text:"Собственник фабрики в Ставрополе пришёл с запросом:"},{type:"quote",text:"«Производство загружено на 90+%, оборот 6,5 млн в месяц, а чистая прибыль — болтается в районе 400 тыс. рублей. Не складывается»."},{type:"h3",text:"Проблема"},{type:"p",text:"Логистика производства работала по принципу «кто громче кричит», а не по экономической целесообразности."},{type:"p",text:"На аудите нам удалось выявить:"},{type:"list",items:["Менеджеры тратили **70% времени** на **30% клиентов** с мелкими, но «срочными» заказами (кухни до 250 тыс. ₽).","Производство постоянно ставило эти заказы в приоритет, срывая сроки по сложным проектам (гарнитуры от 1,5 млн ₽)."]},{type:"p",text:"В итоге: уходили крупные клиенты, оставляя негативные отзывы, которые блокировали приток новых платёжеспособных заказчиков."},{type:"h3",text:"Решение: конкретные шаги"},{type:"steps",items:["Внедрили цифровую канбан-доску (в Битрикс24) для визуализации загрузки цеха.","Ввели алгоритм расстановки приоритетов. Каждый заказ получал коэффициент — **плановая маржа ÷ трудоёмкость в часах**.","Установили правило: заказы с коэффициентом ниже **5 000 ₽/час** согласовывались с директором и ставились в график только при наличии свободных мощностей.","Разработали скрипт для менеджеров для вежливого отказа от невыгодных проектов с перенаправлением в низкий сезон."]},{type:"h3",text:"Результат за 2 месяца"},{type:"steps",items:["Количество маломаржинальных заказов (до 200 тыс. ₽) сократилось на **40%**.","Средняя маржинальность проекта выросла с **18% до 28%**.","Соблюдение сроков по крупным заказам — **94%**.","Чистая прибыль выросла на **400 000 ₽ в месяц** за счёт выполнения 3–4 дополнительных крупных проектов вместо 10–12 мелких."]},{type:"note",text:"P.S. Управление производством — это не про скорость, а про рентабельность времени вашего оборудования и сотрудников. Мы помогаем выстроить систему, где приоритеты определяются не эмоциями, а экономикой."}]}],g=[...m].sort((t,e)=>(e.published??"").localeCompare(t.published??"")),d=g.slice(0,4);t.s(["allTags",0,function(){let t=new Map;for(let e of m)for(let i of e.tags)t.set(i,(t.get(i)??0)+1);return[...t.entries()].map(([t,e])=>({tag:t,count:e})).sort((t,e)=>e.count-t.count)},"getArticle",0,t=>m.find(e=>e.slug===t&&(e.body||e.customPage)),"homePosts",0,d,"postsByDate",0,g,"readingMinutes",0,function(t){if(!t.body)return 0;let e=t=>t.split(/\s+/).filter(Boolean).length,i=e(t.shortAnswer??""),s=0;for(let a of t.body){if("text"in a&&"string"==typeof a.text&&(i+=e(a.text)),"items"in a&&Array.isArray(a.items))for(let t of a.items)i+=e("string"==typeof t?t:"v"in t?`${t.v} ${t.l}`:`${t.title} ${t.text}`);if("table"===a.type)for(let t of(s+=10,a.rows))i+=e(t.join(" "));"image"===a.type&&(s+=10)}for(let s of t.faq??[])i+=e(`${s.q} ${s.a}`);return Math.max(1,Math.round(i/170+s/60))}],88834)}]);